"""Source-only static analysis of a VIKTOR app.

Derives each view's **input-dependency contract** — the ``params`` paths it may read on any
branch — plus, for input the params contract cannot express, the **external services** it reads
(and the platform-service clients it constructs) — by parsing the app's ``.py`` files (``ast``)
*without importing the app*.

A param path is a tuple of ``str`` segments: ``params.section.width`` -> ``('section', 'width')``.
List access is not tracked per element — the analyzer stops at the list node
(``params.loads[i].x`` -> ``('loads',)``).

Soundness (over-approximate, never under-approximate): any access the analyzer cannot resolve
statically *escalates* to a whole-subtree dependency (or the full params set ``*`` at the root)
rather than being dropped. The set may over-approximate but never omits a real dependency.

Names, attributes, and calls resolve through a project index built by parsing every ``.py`` file
under the app root: per-module symbol tables and an import graph, following calls only into the
app package. Anything binding outside the app (stdlib / ``viktor`` / site-packages) or otherwise
unresolvable escapes, keeping the analysis sound.
"""

from __future__ import annotations

import ast
import builtins
import contextlib
import functools
import os
from collections.abc import Generator, Iterator
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, NamedTuple

ParamPath = tuple[str, ...]  # dict / attr-key segments, e.g. ('section', 'width')

_SELF = "@self"  # reserved env key -> {attr: Path}: bindings for `self.x` inside a followed method
_DYN = object()  # subscript/get key that is not a resolvable string (int index, variable, slice)
_MAX_DEPTH = 25  # interprocedural recursion backstop, shared by params-following and detection scans
_LOOP_PASSES = 5  # max fixpoint re-walks of a loop body (see `_Analyzer._walk_loop`)

# Munch/dict read-enumeration methods: reading these consumes the whole node (all keys).
_BULK_METHODS = {"keys", "values", "items", "copy", "toDict"}

# Builtins that inspect a params node's presence / size / type / truthiness *without* handing
# back a traversable child. Deliberately excludes anything that returns/exposes a descendant
# (getattr) or deep-reads (str/repr/format).
_SHALLOW_BUILTINS = {"hasattr", "len", "isinstance", "bool", "type", "callable", "id"}

# SDK origins giving a view access to platform state the params contract cannot enumerate, by the
# label they carry. Matched on a prefix: any name under `viktor.api_v1` is API data, a *result* type
# (`Entity`, `EntityList`) as much as the client that fetched it.
_PLATFORM_ORIGINS: dict[tuple[str, ...], str] = {
    ("viktor", "api_v1"): "api",
    ("viktor", "API"): "api",
    ("viktor", "Storage"): "storage",
    ("viktor", "core", "Storage"): "storage",
}

_EXTERNAL_PROGRAM_ORIGIN = ("viktor", "external")

# Names under `viktor.external` that **run third-party software on a worker**, matched on a segment
# of the origin. A prefix rule cannot serve here: of the ~230 public names under it, these are the
# ones that run something, and the rest either describe a job without running it (`SurfaceLoad`,
# `LoadCase.Duration.SHORT`) or hand data to a deterministic platform add-on — `render_word_file`
# filling a template, `scia.Model.generate_xml_input()` serialising a model, `SpreadsheetCalculation`
# evaluating a macro-free sheet. Those post over the network, but the same input yields the same
# output, so there is nothing for a consumer to invalidate on.
#
# Derived from the SDK as every `ExternalProgram` subclass (they own `execute`), plus `connect`/
# `attach` for the interactive sessions `sap2000` and `etabs` expose, plus the OAuth2 client, whose
# token comes from a third-party identity provider. A new integration needs adding here and is a
# miss until it is — the cheaper direction for a label the consumer is unlikely to gate on
# (README § Result shape).
_EXTERNAL_PROGRAM_NAMES = frozenset(
    {
        "AxisVMAnalysis", "DFoundationsAnalysis", "DGeoStabilityAnalysis", "DSettlementAnalysis",
        "DSheetPilingAnalysis", "DStabilityAnalysis", "DynamoAnalysis", "ETABSAnalysis",
        "Excel", "ExternalProgram", "GRLWeapAnalysis", "GenericAnalysis", "GrasshopperAnalysis",
        "IdeaRcsAnalysis", "MatlabAnalysis", "OAuth2Integration", "PlaxisAnalysis",
        "PythonAnalysis", "RFEMAnalysis", "RevitAnalysis", "RobotAnalysis", "SAP2000Analysis",
        "SciaAnalysis", "TeklaAnalysis", "attach", "connect",
    }
)  # fmt: skip

# --- external-input classification -------------------------------------------

_EXTERNAL_UNKNOWN = "unknown"  # the analyzer could not see reachable code, so anything may have happened

# Origins that carry a capability, grouped by the tag they carry. Longest matching prefix wins, and
# an origin matching nothing at all is pure: these tables name **capability, not purity**. An
# unlisted library is assumed to compute rather than to read, which is where this pass draws its line
# (see the README's § Soundness) — the alternative flags every app importing something the tables
# have never heard of. A library's read surface is covered by name instead (`_READ_LEAF_NAMES`), so
# `openpyxl.load_workbook` needs no entry of its own.
# fmt: off
_CAPABILITY_ORIGINS: dict[str, tuple[tuple[str, ...], ...]] = {
    # the network, whatever the client wraps: HTTP, mail, cloud SDKs, DB drivers
    "http": (
        ("requests",), ("httpx",), ("urllib",), ("urllib3",), ("http",), ("socket",),
        ("ftplib",), ("smtplib",), ("poplib",), ("imaplib",), ("aiohttp",), ("websockets",),
        ("paramiko",), ("boto3",), ("botocore",), ("azure",), ("google", "cloud"),
        ("snowflake",), ("openai",), ("anthropic",), ("psycopg",), ("psycopg2",),
        ("pymysql",), ("sqlalchemy",), ("pymongo",), ("redis",),
    ),
    # the clock, read finer than a day: unstable across two evaluations, but it drifts predictably,
    # and a consumer weighs a time-stamped view differently from a random one. `date.today()` is
    # deliberately absent — a `date` is stable for the whole day.
    "clock": (
        ("time",),
        ("datetime", "datetime", "now"),
        ("datetime", "datetime", "utcnow"),
    ),
    # randomness: a value that never comes back, so a recompute never reproduces the old output
    "nondeterminism": (
        ("random",),
        ("secrets",),
        ("uuid",),
        ("numpy", "random"),
        ("os", "urandom"),
    ),
    # local disk (its own tag, not `unknown`: see the consumer-policy note in the README)
    "filesystem": (
        ("pathlib",), ("glob",), ("shutil",), ("tempfile",), ("zipfile",), ("tarfile",),
        ("sqlite3",), ("scipy", "io"),
        ("os", "listdir"), ("os", "walk"), ("os", "scandir"), ("os", "stat"),
        # joining a path is pure; asking the disk is not
        ("os", "path", "exists"), ("os", "path", "isfile"), ("os", "path", "isdir"),
        ("os", "path", "getmtime"), ("os", "path", "getsize"),
    ),
}

# The platform labels classification produces. `_platform_service_tag` is the one rule that produces
# them, for both routes into that dimension, and `_analyze_view_safe` moves them out of the
# external-input result into their own.
_PLATFORM_TAGS = frozenset({"api", "storage", "integrations"})

# Origins sitting *under* one of those prefixes that carry nothing themselves. Longest prefix wins,
# so each of these overrides the capability above it.
_PURE_ORIGINS: tuple[tuple[str, ...], ...] = (
    ("urllib", "parse"),     # URL string manipulation only
    ("time", "sleep"),       # spends time, reads none
    ("time", "strptime"),    # parses a string in hand
    ("time", "mktime"),      # converts a struct in hand
)
# fmt: on

# Dotted origin prefix -> the capability it carries, or `None` for a pure override under one.
_ORIGIN_CAPABILITIES: dict[tuple[str, ...], str | None] = {
    **{origin: tag for tag, origins in _CAPABILITY_ORIGINS.items() for origin in origins},
    **dict.fromkeys(_PURE_ORIGINS),
}

# A library's read surface is conventionally named, so one rule covers all 18 of ``pandas.read_*``,
# plus `openpyxl.load_workbook` and `ezdxf.readfile`, without an entry for any of them. Applied to
# the segments beyond the prefix `_ORIGIN_CAPABILITIES` matched — or beyond the module, when it
# matched nothing. Writes are deliberately absent: a view writing a file produces no input its
# output depends on.
_READ_LEAF_NAMES = frozenset(
    {
        "load", "loadtxt", "genfromtxt", "fromfile", "open", "read", "readfile", "readlines",
        "imread", "from_file", "from_path", "ExcelFile", "HDFStore",
    }
)  # fmt: skip
# `loads` matches none of these, which is what keeps `json.loads` — a string already in hand — pure.
_READ_LEAF_PREFIXES = ("read_", "load_", "open_")

# Environment reads (`os.environ`, `os.getenv`, `sys.argv`) carry no tag: a deployment's config is as
# fixed for the life of its image as the files baked into it, so nothing a view reads there can drift
# under it. `sys.stdin` carries none for the reason `input` does not: a worker has no terminal.

# Builtins that can introduce external input. `builtins` is a closed namespace, so the pure set is
# the remainder rather than an allowlist that would silently miss additions. Reflection (`getattr`,
# `vars`, `dir`, ...) is deliberately absent: it can reach anything, but so does the ordinary app
# code that fetches an attribute by name, and flagging all of that buys nothing.
_IMPURE_BUILTINS: dict[str, str] = {
    "open": "filesystem",
}

# Module dunders are plain values the interpreter sets, never a service.
_PURE_DUNDERS = frozenset({"__file__", "__name__", "__doc__", "__package__", "__spec__", "__loader__"})

_PURE_BUILTINS = (frozenset(dir(builtins)) - frozenset(_IMPURE_BUILTINS)) | _PURE_DUNDERS

_VIEW_DECORATOR_NAMES = frozenset(
    {
        "AutodeskView",
        "DataView",
        "GeoJSONAndDataView",
        "GeoJSONView",
        "GeometryAndDataView",
        "GeometryView",
        "IFCAndDataView",
        "IFCView",
        "ImageAndDataView",
        "ImageView",
        "MapAndDataView",
        "MapView",
        "PDFView",
        "PlotlyAndDataView",
        "PlotlyView",
        "TableView",
        "WebAndDataView",
        "WebView",
    }
)

_CONTROLLER_BASE_NAMES = frozenset({"Controller", "ViktorController"})

_SKIP_DIRS = {"__pycache__", "venv", ".venv"}


@dataclass
class _ViewParamDependency:
    """The statically-derived param-dependency set for a single view.

    - ``paths``: leaf paths the view reads (str dict/attr-key segments).
    - ``escaped_nodes``: paths whose *entire subtree* is a dependency.
    - ``fell_back_to_everything``: the params root escaped -> depends on all params.
    """

    paths: set = field(default_factory=set)
    escaped_nodes: set = field(default_factory=set)
    fell_back_to_everything: bool = False

    def normalized_contract(self) -> set:
        """Prefix-minimal dependency set for this view.

        A returned path denotes that node *and its whole subtree*, so any entry with a strict
        ancestor already present is redundant and dropped. ``{"*"}`` = depends on all params.
        """
        if self.fell_back_to_everything:
            return {"*"}

        # A whole-params escape sets ``fell_back_to_everything`` (handled above), so the empty path
        # never reaches ``paths``/``escaped_nodes`` and every node here has >= 1 segment.
        nodes = self.paths | self.escaped_nodes  # leaf vs subtree is irrelevant to the emitted shape

        def _has_ancestor(node: tuple) -> bool:  # a strict prefix is present -> its subtree already covers this
            return any(node[:i] in nodes for i in range(1, len(node)))

        return {".".join(node) for node in nodes if not _has_ancestor(node)}


@dataclass
class _ViewDependencyResult:
    """The per-view facts a single analyzer walk derives — one field per analysis dimension."""

    params: _ViewParamDependency
    platform_services: set = field(default_factory=set)
    external_services: set = field(default_factory=set)


# --- pure AST helpers (resolution-independent) --------------------------------


_FuncDef = (ast.FunctionDef, ast.AsyncFunctionDef)


def _const_key(slice_node: ast.AST) -> Any:
    """Resolve a subscript key to a dict-key path segment (a literal ``str``), else ``_DYN``.

    A list index (``[0]``, ``[i]``) is *not* a dict key -> ``_DYN``: the caller stops at the list
    node rather than descending into a specific element.
    """
    if isinstance(slice_node, ast.Constant) and isinstance(slice_node.value, str):
        return slice_node.value
    return _DYN  # int index, variable key/index, slice, etc. -> caller stops at / escapes the base


def _literal_str_arg(args: list) -> str | None:
    if args and isinstance(args[0], ast.Constant) and isinstance(args[0].value, str):
        return args[0].value
    return None


def _params_path(node: ast.AST, env: Env) -> ParamPath | None:
    """Resolve a pure params-rooted *reference chain* to its path, else ``None``.

    Handles ``Name`` (via the alias env), attribute access, constant-key subscripts,
    and ``x.get('literal')``. Returns ``None`` for anything that is not a clean,
    statically-resolvable reference (the caller then escapes or recurses).
    """
    if isinstance(node, ast.Name):
        value = env.get(node.id)
        return value if isinstance(value, tuple) else None  # tuple = params path; _Instance/None -> not a ref
    if isinstance(node, ast.Attribute):
        # `self.<attr>` inside a followed method resolves via the instance's params-bindings.
        if isinstance(node.value, ast.Name) and node.value.id == "self":
            self_bindings = env.get(_SELF)
            if isinstance(self_bindings, dict) and node.attr in self_bindings:
                return self_bindings[node.attr]
        base = _params_path(node.value, env)
        if base is None or node.attr in _BULK_METHODS:
            return None
        return (*base, node.attr)
    if isinstance(node, ast.Subscript):
        base = _params_path(node.value, env)
        if base is None:
            return None
        key = _const_key(node.slice)
        if key is _DYN:
            return None
        return (*base, key)
    if isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Attribute) and func.attr == "get":
            base = _params_path(func.value, env)
            key = _literal_str_arg(node.args)
            if base is None or key is None:
                return None
            return (*base, key)
        return None
    return None


def _target_names(target: ast.AST) -> list:
    if isinstance(target, ast.Name):
        return [target.id]
    if isinstance(target, (ast.Tuple, ast.List)):
        names: list = []
        for elt in target.elts:
            names.extend(_target_names(elt))
        return names
    return []


def _is_self_attr(node: ast.AST) -> bool:
    return isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id == "self"


@functools.cache
def _derive_locals(node: ast.AST) -> tuple:
    """Nested defs, ever-assigned names, and single-assignment calls in ``node``'s body.

    Cached because the same function node is re-entered from multiple call sites (once per
    view that calls it, and once per callsite within a view), and this ``ast.walk`` over the
    whole body would otherwise redo identical work each time. Parsing each module once (see
    ``_build_project_index``) makes every node object process-stable, so identity caching holds.

    The third result maps ``{name: Call}`` for every local bound exactly once, from a plain call, and
    never a parameter: such a name can only hold what that one call returned, which is what lets
    detection type a method-call receiver (see ``_scan_receiver_method``) with no flow analysis. A
    name bound more than once could name a different object at the call site, so it is left out.
    """
    local_defs: dict = {}
    assigned_names: set = set()
    store_counts: dict = {}
    call_bindings: dict = {}
    for n in ast.walk(node):
        if n is node:
            continue
        if isinstance(n, _FuncDef):
            local_defs.setdefault(n.name, n)
        elif isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store):
            assigned_names.add(n.id)
            store_counts[n.id] = store_counts.get(n.id, 0) + 1
        elif isinstance(n, (ast.Assign, ast.AnnAssign)):
            targets = n.targets if isinstance(n, ast.Assign) else [n.target]
            if len(targets) == 1 and isinstance(targets[0], ast.Name) and isinstance(n.value, ast.Call):
                call_bindings[targets[0].id] = n.value
    args = node.args
    params = {a.arg for a in (args.posonlyargs + args.args + args.kwonlyargs)}
    single_calls = {k: v for k, v in call_bindings.items() if store_counts.get(k) == 1 and k not in params}
    return local_defs, assigned_names, single_calls


def _find_params_param(node: ast.AST) -> str | None:
    """The view receives its params under the keyword ``params`` (SDK convention)."""
    args = node.args
    names = {a.arg for a in (args.posonlyargs + args.args + args.kwonlyargs)}
    return "params" if "params" in names else None


@functools.cache
def _writeback_names(funcdef: ast.AST) -> frozenset:
    """Names ``funcdef``'s body declares ``global`` / ``nonlocal`` -- assignments to them bind an
    *outer* scope, not this function's locals. Keyed on the node itself.

    Recurses down the body's statements/expressions, stopping at a nested function / lambda / class
    (each is its own scope, with its own ``global``/``nonlocal``); every call is on a strictly
    smaller child, so it terminates. A ``global``/``nonlocal`` may sit inside an ``if``/``for``/...
    block, so those are descended into. Cached because a closure is re-analysed from multiple call
    sites and re-walked across loop-fixpoint passes, so this body walk would otherwise redo identical
    work each time (parsing each module once makes every node object process-stable, so the cache holds).
    """
    names: set = set()

    def collect(node: ast.AST) -> None:
        if isinstance(node, (ast.Global, ast.Nonlocal)):
            names.update(node.names)
        elif not isinstance(node, (*_FuncDef, ast.Lambda, ast.ClassDef)):
            for child in ast.iter_child_nodes(node):
                collect(child)

    for stmt in funcdef.body:
        collect(stmt)
    return frozenset(names)


def _platform_service_tag(origin: tuple) -> str | None:
    """The `platform_services` label ``origin`` carries, else ``None``.

    The single authority for both routes into that dimension — a positively identified construction
    and a mention classified by the external-input pass, which reaches this through `_origin_class`.
    Stating it twice would let the two drift, and the same read would then land in different
    dimensions depending on how the app happened to spell it.
    """
    if origin[: len(_EXTERNAL_PROGRAM_ORIGIN)] == _EXTERNAL_PROGRAM_ORIGIN:
        # a worker integration is named, not prefixed: see `_EXTERNAL_PROGRAM_NAMES`
        return "integrations" if set(origin) & _EXTERNAL_PROGRAM_NAMES else None
    for i in range(len(origin), 0, -1):
        if origin[:i] in _PLATFORM_ORIGINS:
            return _PLATFORM_ORIGINS[origin[:i]]
    return None


def _leaf_class(segment: str) -> str | None:
    """``"filesystem"`` when an origin segment names a library's read, else ``None``.

    Every read maps to `filesystem`, `read_csv` included, though it takes a path *or* a URL:
    guessing the common case is what buys not flagging every app that reads a file it shipped with.
    """
    if segment in _READ_LEAF_NAMES or segment.startswith(_READ_LEAF_PREFIXES):
        return "filesystem"
    return None


def _origin_class(origin: tuple) -> str | None:
    """The tag ``origin`` carries, or ``None`` if it introduces no external input.

    Longest matching prefix wins. An origin matching no prefix carries no capability, so what is
    left to look at is its read surface: every segment past the module name goes through
    `_leaf_class`, which is why ``pandas.read_csv`` flags while ``pandas.DataFrame`` does not.
    """
    platform = _platform_service_tag(origin)
    if platform is not None:
        return platform  # `_analyze_view_safe` routes this into `platform_services`
    matched = 0
    for i in range(len(origin), 0, -1):
        if origin[:i] in _ORIGIN_CAPABILITIES:
            tag = _ORIGIN_CAPABILITIES[origin[:i]]
            if tag is not None:
                return tag
            matched = i  # a pure override under a capability prefix (`urllib.parse`, `time.sleep`)
            break
    leaf_tags = (_leaf_class(segment) for segment in origin[max(matched, 1) :])
    return next((leaf for leaf in leaf_tags if leaf is not None), None)


@functools.cache
def _body_references(funcdef: ast.AST) -> tuple:
    """`_collect_references` over a function body, nested scopes included."""
    return _collect_references(funcdef, skip_functions=False)


@functools.cache
def _import_time_references(tree: ast.Module) -> tuple:
    """`_collect_references` over a module's import-time code only (function bodies skipped)."""
    return _collect_references(tree, skip_functions=True)


def _collect_references(root: ast.AST, skip_functions: bool) -> tuple:  # noqa: C901
    """``(maximal chains, names bound anywhere inside, {name: origin} for local imports)``.

    One traversal, since every classification needs all three and the walk is the expensive part.
    Chains are maximal so ``os.path.join`` is not also read as a mention of ``os``; descent still
    enters the non-chain parts of a base, e.g. the subscript in ``lookup[i].attr``. Bound names
    cover nested scopes too, and are what stops ``rows.append(...)`` flagging every view.

    ``skip_functions`` collects a module's import-time code instead: a ``def``'s body is skipped
    (classified when a view reaches it), while class bodies and lambdas stay in — both run at import.
    """
    chains: set = set()
    bound: set = set()
    imports: dict = {}
    stack: list = [root]
    while stack:
        node = stack.pop()
        if isinstance(node, ast.Name):
            chains.add((node.id, ()))
            if isinstance(node.ctx, (ast.Store, ast.Del)):
                bound.add(node.id)
            continue  # a bare Name has no child nodes
        if isinstance(node, ast.Attribute):
            attrs: list = []
            base: ast.AST = node
            while isinstance(base, ast.Attribute):
                attrs.append(base.attr)
                base = base.value
            if isinstance(base, ast.Name):
                chains.add((base.id, tuple(reversed(attrs))))
            else:  # rooted in a computed value: no origin of its own, but its parts have mentions
                stack.extend(ast.iter_child_nodes(base))
            continue
        if isinstance(node, (*_FuncDef, ast.Lambda)):
            if skip_functions and isinstance(node, _FuncDef) and node is not root:
                bound.add(node.name)  # a def binds its name at import time; its body does not run
                continue
            # a lambda is *not* skipped: `sorted(x, key=lambda v: ...)` at module level runs its
            # body at import, and no view walk would ever reach it
            args = node.args
            bound.update(a.arg for a in (args.posonlyargs + args.args + args.kwonlyargs))
            for extra in (args.vararg, args.kwarg):
                if extra is not None:
                    bound.add(extra.arg)
            if isinstance(node, _FuncDef):
                bound.add(node.name)
        elif isinstance(node, ast.ClassDef) or (isinstance(node, ast.ExceptHandler) and node.name):
            bound.add(node.name)
        elif isinstance(node, ast.Import):
            for alias in node.names:
                # `import a.b.c` binds `a`; `import a.b as ab` binds `ab` to the full path
                dotted = alias.name if alias.asname else alias.name.split(".")[0]
                imports[alias.asname or dotted] = tuple(dotted.split("."))
        elif isinstance(node, ast.ImportFrom) and node.module and not node.level:
            for alias in node.names:
                imports[alias.asname or alias.name] = (*node.module.split("."), alias.name)
        stack.extend(ast.iter_child_nodes(node))
    return frozenset(chains), frozenset(bound), imports


# --- project / module model --------------------------------------------------


class ModuleInfo:
    """One parsed app source file, addressed by its dotted module name."""

    def __init__(
        self, dotted_name: str, file_path: str, is_package: bool, tree: ast.Module | None, parse_error: bool
    ) -> None:
        self.dotted_name = dotted_name
        self.file_path = file_path
        self.is_package = is_package
        self.tree = tree
        self.parse_error = parse_error
        self._symbols: dict | None = None  # built lazily by `_module_symbols`


class ProjectIndex:
    """All parsed app modules, keyed by dotted name, plus a ClassInfo cache."""

    def __init__(self) -> None:
        self.modules: dict = {}
        self._classinfos: dict = {}  # id(ClassDef) -> ClassInfo

    def resolve_module(self, dotted: str) -> ModuleInfo | None:
        return self.modules.get(dotted)

    def classinfo(self, classdef: ast.ClassDef, module: ModuleInfo) -> ClassInfo:
        ci = self._classinfos.get(id(classdef))
        if ci is None:
            ci = ClassInfo(self, classdef, module)
            self._classinfos[id(classdef)] = ci
        return ci


def _build_project_index(source_root: str | Path) -> ProjectIndex:
    """Parse every ``.py`` under ``source_root`` once and index it by dotted module name.

    Dotted naming: the path relative to the root, ``.py`` dropped, a trailing ``__init__``
    dropped. If ``source_root`` is itself a package (has ``__init__.py``) its directory name
    becomes the top package, so pointing at ``.../app/`` yields ``app``, ``app.project.controller``,
    ... — matching both the single-``app.py`` and the ``app/`` package layouts.
    """
    root = Path(source_root)
    base_parts = [root.name] if (root / "__init__.py").is_file() else []
    project = ProjectIndex()
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in _SKIP_DIRS and not d.startswith(".")]
        for fn in filenames:
            if not fn.endswith(".py"):
                continue
            fpath = Path(dirpath) / fn
            rel = fpath.relative_to(root)
            parts = base_parts + list(rel.parts[:-1])
            if rel.stem != "__init__":
                parts.append(rel.stem)
            dotted = ".".join(p for p in parts if p)
            try:
                tree: ast.Module | None = ast.parse(fpath.read_text(encoding="utf-8"))
                parse_error = False
            except (SyntaxError, ValueError, OSError, UnicodeDecodeError):
                tree, parse_error = None, True
            project.modules[dotted] = ModuleInfo(dotted, str(fpath), fn == "__init__.py", tree, parse_error)
    return project


# --- bindings + per-module symbol table --------------------------------------
# A Binding is what a top-level name is bound to in a module, before resolution: a local
# definition, a module-level alias, or an import.


@dataclass
class LocalClass:
    classdef: ast.ClassDef


@dataclass
class LocalFunc:
    funcdef: ast.AST


@dataclass
class LocalAlias:
    value: ast.AST  # a module-level `x = <Name/Attribute chain>` — resolved lazily


@dataclass
class OpaqueLocal:
    """A module-level name bound to something unresolvable — it *shadows* (so builtins / imports
    of the same name don't apply) but resolves to nothing.

    ``value`` is the expression that built it, for `_module_value_services` to classify; ``None``
    when no assignment bound the name, e.g. an unresolvable ``from ... import``.
    """

    value: ast.AST | None = None


@dataclass
class ImportModule:
    target: str  # dotted module the name is bound to (`import a.b as z` -> 'a.b'; `import a.b` -> 'a')


@dataclass
class ImportName:
    origin_module: str  # `from M import n` -> 'M'
    origin_attr: str  # -> 'n'


# What a top-level name is bound to in a module, before name resolution.
Binding = LocalClass | LocalFunc | LocalAlias | OpaqueLocal | ImportModule | ImportName


def _resolve_from_module(module: ModuleInfo, stmt: ast.ImportFrom) -> str | None:
    """Absolute dotted module a ``from ... import`` targets, resolving relative (leading-dot) form."""
    if stmt.level == 0:
        return stmt.module
    parts = module.dotted_name.split(".") if module.is_package else module.dotted_name.split(".")[:-1]
    if stmt.level - 1 > len(parts):
        return None  # more dots than package depth -> unresolvable
    anchor = parts[: len(parts) - (stmt.level - 1)]
    if stmt.module:
        anchor = anchor + stmt.module.split(".")
    return ".".join(anchor) or None


def _module_symbols(module: ModuleInfo) -> dict[str, Binding]:  # noqa: C901
    """Top-level ``name -> Binding`` for a module, built once (lazily) and cached."""
    if module._symbols is not None:
        return module._symbols
    syms: dict = {}
    module._symbols = syms  # set before walking so a self-referential import can't loop
    if module.tree is None:
        return syms
    for stmt in module.tree.body:
        if isinstance(stmt, ast.ClassDef):
            syms[stmt.name] = LocalClass(stmt)
        elif isinstance(stmt, _FuncDef):
            syms[stmt.name] = LocalFunc(stmt)
        elif isinstance(stmt, ast.Import):
            for alias in stmt.names:
                if alias.asname:
                    syms[alias.asname] = ImportModule(alias.name)
                else:  # `import a.b.c` binds the top name `a` to package `a`
                    top = alias.name.split(".")[0]
                    syms[top] = ImportModule(top)
        elif isinstance(stmt, ast.ImportFrom):
            origin = _resolve_from_module(module, stmt)
            if stmt.names and stmt.names[0].name == "*":
                # star-imported names stay unresolved -> they escape (sound). External-service
                # classification recovers what it can from the origin (`_star_import_origins`).
                continue
            for alias in stmt.names:
                bound = alias.asname or alias.name
                syms[bound] = ImportName(origin, alias.name) if origin else OpaqueLocal()
        elif isinstance(stmt, (ast.Assign, ast.AnnAssign)):
            targets = stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]
            for t in targets:
                if isinstance(t, ast.Name):
                    if isinstance(stmt.value, (ast.Name, ast.Attribute)):
                        syms[t.id] = LocalAlias(stmt.value)
                    elif stmt.value is not None:
                        syms[t.id] = OpaqueLocal(stmt.value)
    return syms


# --- name resolution ----------------------------------------------------------
# What a name / attribute chain resolves to: an in-app definition (AppFunc / AppClass /
# AppModule), or an External origin (a dotted path outside the app — stdlib / viktor /
# site-packages). External and None both mean "unfollowable" and cause the caller to escape.


@dataclass
class AppFunc:
    funcdef: ast.AST
    home_module: ModuleInfo  # the module whose symbol table the body resolves against
    owner: ClassInfo | None  # defining class (for `self.x`) or None for a module-level func


@dataclass
class AppClass:
    classinfo: ClassInfo


@dataclass
class AppModule:
    module: ModuleInfo


@dataclass
class External:
    origin: tuple[str, ...]  # dotted origin, e.g. ('viktor', 'views', 'GeometryView')


# What a name / attribute chain resolves to. External and None both mean "unfollowable".
Resolution = AppFunc | AppClass | AppModule | External | None


def resolve_name(
    project: ProjectIndex, name: str, module: ModuleInfo, _visited: frozenset[tuple[str, str, str]] | None = None
) -> Resolution:
    """Resolve a top-level name in ``module`` to an ``App*``/``External`` result, or ``None``."""
    binding = _module_symbols(module).get(name)
    if binding is None:
        return None  # builtin / unknown -> not followable (caller escapes)
    return resolve_binding(project, binding, module, _visited or frozenset())


def resolve_binding(
    project: ProjectIndex, binding: Binding, module: ModuleInfo, _visited: frozenset[tuple[str, str, str]]
) -> Resolution:
    if isinstance(binding, LocalClass):
        return AppClass(project.classinfo(binding.classdef, module))
    if isinstance(binding, LocalFunc):
        return AppFunc(binding.funcdef, module, None)
    if isinstance(binding, LocalAlias):
        return resolve_ref_chain(project, binding.value, module, _visited)
    if isinstance(binding, ImportModule):
        m = project.resolve_module(binding.target)
        return AppModule(m) if m is not None else External(tuple(binding.target.split(".")))
    if isinstance(binding, ImportName):
        key = ("name", binding.origin_module, binding.origin_attr)
        if key in _visited:
            return None
        _visited = _visited | {key}
        m = project.resolve_module(binding.origin_module)
        if m is not None:
            return resolve_attr(project, AppModule(m), binding.origin_attr, _visited)
        return External((*binding.origin_module.split("."), binding.origin_attr))
    return None  # OpaqueLocal


def resolve_attr(
    project: ProjectIndex, base: Resolution, attr: str, _visited: frozenset[tuple[str, str, str]] | None = None
) -> Resolution:
    """Resolve ``base.attr`` where ``base`` is a prior resolution result."""
    _visited = _visited or frozenset()
    if isinstance(base, AppModule):
        binding = _module_symbols(base.module).get(attr)
        if binding is not None:
            return resolve_binding(project, binding, base.module, _visited)
        sub = f"{base.module.dotted_name}.{attr}" if base.module.dotted_name else attr
        m = project.resolve_module(sub)
        return AppModule(m) if m is not None else None
    if isinstance(base, External):
        return External((*base.origin, attr))
    if isinstance(base, AppClass):
        member = base.classinfo.own_member(attr)
        if member is None:
            return None
        node, _ = member
        if isinstance(node, ast.ClassDef):
            return AppClass(project.classinfo(node, base.classinfo.module))
        return AppFunc(node, base.classinfo.module, base.classinfo)
    return None


def resolve_ref_chain(
    project: ProjectIndex, node: ast.AST, module: ModuleInfo, _visited: frozenset[tuple[str, str, str]] | None = None
) -> Resolution:
    """Resolve a ``Name`` / ``Attribute`` chain (e.g. a decorator or call target) end to end."""
    if isinstance(node, ast.Name):
        return resolve_name(project, node.id, module, _visited)
    if isinstance(node, ast.Attribute):
        base = resolve_ref_chain(project, node.value, module, _visited)
        return resolve_attr(project, base, node.attr, _visited) if base is not None else None
    return None


# --- external-service classification ------------------------------------------


@functools.cache
def _class_level_assignments(classdef: ast.ClassDef) -> dict:
    """``{name: value expression}`` for each assignment directly in a class body."""
    values: dict = {}
    for stmt in classdef.body:
        if isinstance(stmt, (ast.Assign, ast.AnnAssign)) and stmt.value is not None:
            targets = stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]
            for target in targets:
                if isinstance(target, ast.Name):
                    values[target.id] = stmt.value
    return values


@functools.cache
def _self_assignments(funcdef: ast.AST) -> dict:
    """``{attr: value expression}`` for each ``self.<attr> = <value>`` in ``funcdef``.

    Annotated form included (``self.params: Munch = params``): missing it leaves the attribute
    unattributed, which reads as `_EXTERNAL_UNKNOWN` however pure the value was.
    """
    values: dict = {}
    for node in ast.walk(funcdef):
        if not isinstance(node, (ast.Assign, ast.AnnAssign)) or node.value is None:
            continue
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        for target in targets:
            if isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name) and target.value.id == "self":
                values[target.attr] = node.value
    return values


def _chain_services(
    chains: frozenset,
    bound: frozenset,
    local_imports: dict,
    module: ModuleInfo,
    owner: ClassInfo | None,
    project: ProjectIndex,
    seen: frozenset = frozenset(),
) -> frozenset:
    """Classify a set of maximal chains, folding in whatever built the values they read."""
    tags: set = set()
    for name, attrs in chains:
        chain_tags, source = _classify_reference(name, attrs, bound, local_imports, module, owner, project, seen)
        tags |= chain_tags
        if source is not None:
            tags |= _module_value_services(source[0], source[1], project)
    return frozenset(tags)


def _expression_services(
    value: ast.AST,
    module: ModuleInfo,
    project: ProjectIndex,
    bound: frozenset,
    local_imports: dict,
    seen: frozenset = frozenset(),
) -> frozenset:
    """Tags carried by one expression, read in the scope that surrounds it.

    ``bound``/``local_imports`` come from that enclosing scope: without them a value as ordinary as
    ``self.x = param`` would classify ``param`` as an unresolvable free name. ``seen`` carries the
    attributes already being attributed, so a cycle between two of them terminates.
    """
    chains, _, _ = _collect_references(value, skip_functions=False)
    return _chain_services(chains, bound, local_imports, module, None, project, seen)


@functools.cache
def _class_attr_services(owner: ClassInfo, attr: str, project: ProjectIndex, seen: frozenset) -> frozenset:
    """Tags for an attribute of app class ``owner``: what built it, or ``unknown`` when nothing in
    the app does.

    Serves both ways an attribute is reached — ``self.<attr>`` inside the class, and ``Cls.<attr>``
    by name. A controller is constructed by the platform, so its class body and ``__init__`` run
    before any view yet are reachable from no app code. Attribution is per attribute rather than per
    class, so a view reading one pure constant does not inherit the fetch that built its neighbour.
    """
    if (id(owner.classdef), attr) in seen:
        return frozenset()  # cycle through attributes that reference each other
    seen = seen | {(id(owner.classdef), attr)}
    tags: set = set()
    assigned_somewhere = False
    for ci in owner.mro():
        value = _class_level_assignments(ci.classdef).get(attr)
        if value is not None:
            assigned_somewhere = True
            _, bound_here, imports_here = _collect_references(ci.classdef, skip_functions=True)
            tags |= _expression_services(value, ci.module, project, bound_here, imports_here, seen)
        # any method may be the one that set it, so every assignment is a candidate
        for stmt in ci.classdef.body:
            if not isinstance(stmt, _FuncDef):
                continue
            assigned = _self_assignments(stmt).get(attr)
            if assigned is not None:
                assigned_somewhere = True
                _, bound_here, imports_here = _body_references(stmt)
                tags |= _expression_services(assigned, ci.module, project, bound_here, imports_here, seen)
    if assigned_somewhere:
        return frozenset(tags)
    found = owner.lookup_member(attr)
    if found is None:
        return frozenset({_EXTERNAL_UNKNOWN})  # defined outside the app -> unseeable
    node, defining_ci, _ = found
    if isinstance(node, _FuncDef):
        # a member referenced rather than called is never walked, so fold its body in here
        return _body_external_services(node, defining_ci.module, defining_ci, project, seen)
    return frozenset()


@functools.cache
def _body_external_services(
    funcdef: ast.AST, module: ModuleInfo, owner: ClassInfo | None, project: ProjectIndex, seen: frozenset = frozenset()
) -> frozenset:
    """The external-service tags one function body's own code carries.

    Classifies the whole body rather than hooking `_visit_call`, so completeness within a body does
    not depend on where params-tracking happens to recurse. Reachability of *other* bodies stays the
    params walk's and `_scan_callee_detected`'s business; `_enter` escalates what neither reaches.

    Classifying references rather than call targets also catches a callee pulled out of a container
    (``handlers['get'](url)``), where the ``requests.get`` mention is all there is to see.

    Cached per body — the result depends only on the body and its module, never on the calling view.
    """
    chains, bound, local_imports = _body_references(funcdef)
    return _chain_services(chains, bound, local_imports, module, owner, project, seen)


@functools.cache
def _module_level_assignments(module: ModuleInfo) -> dict:
    """``{name: value expression}`` for each module-level plain assignment.

    Read back off the symbol table rather than re-scanning ``module.tree``: `_module_symbols`
    already decides which statements bind a module-level name, and a second scan of the same
    statements would be one more place to keep that decision in sync.
    """
    return {
        name: binding.value
        for name, binding in _module_symbols(module).items()
        if isinstance(binding, (LocalAlias, OpaqueLocal)) and binding.value is not None
    }


@functools.cache
def _module_value_services(module: ModuleInfo, name: str, project: ProjectIndex) -> frozenset:
    """Tags carried by the expression that built module-level value ``module.name``.

    Per value, not per module: reading a plain constant must not inherit the fetch that built its
    neighbour. Transitive, via a worklist rather than recursion so a cycle of constants terminates.
    """
    tags: set = set()
    seen = {(module.dotted_name, name)}
    work = [(module, name)]
    while work:
        # every module reaching the worklist parsed (`_module_level_value_source` requires it), so
        # `tree` is never None here
        current, current_name = work.pop()
        assignments = _module_level_assignments(current)
        value = assignments.get(current_name)
        if value is None:
            continue
        # Module-level assigned names are excluded from `bound` so that a reference to another
        # module-level value routes through resolution and is followed here, rather than being
        # taken for a local. Comprehension and loop variables stay bound.
        _, bound, local_imports = _import_time_references(current.tree)
        bound = bound - frozenset(assignments)
        chains, _, _ = _collect_references(value, skip_functions=False)
        for chain_name, attrs in chains:
            chain_tags, source = _classify_reference(chain_name, attrs, bound, local_imports, current, None, project)
            tags |= chain_tags
            if source is not None and (source[0].dotted_name, source[1]) not in seen:
                seen.add((source[0].dotted_name, source[1]))
                work.append(source)
    return frozenset(tags)


def _module_level_value_source(name: str, module: ModuleInfo, project: ProjectIndex) -> tuple | None:
    """``(module, name)`` of the module-level value ``name`` holds, or ``None`` if it is not one.

    Such a name resolves to nothing followable but is not *unknown* — it holds what one import-time
    expression built. Separating the two keeps a name from an unparseable module flagged.
    """
    binding = _module_symbols(module).get(name)
    if isinstance(binding, OpaqueLocal):
        return module, name
    if isinstance(binding, ImportName):
        origin = project.resolve_module(binding.origin_module)
        if (
            origin is not None
            and not origin.parse_error
            and isinstance(_module_symbols(origin).get(binding.origin_attr), OpaqueLocal)
        ):
            return origin, binding.origin_attr
    return None


@functools.cache
def _star_import_origins(module: ModuleInfo, project: ProjectIndex) -> tuple:
    """Origins of ``module``'s ``from X import *`` statements, all of which are outside the app.

    A star-imported name binds no symbol (`_module_symbols` skips it), so the origin it came from is
    the only evidence left about what it is — enough to tell a parametrization field from a client.
    Empty when the module stars an app module or something that does not resolve: the name could
    then be anything the app defines, and stays unknown.
    """
    if module.tree is None:  # pragma: no cover - a module that did not parse has no body to classify
        return ()
    origins: list = []
    for stmt in module.tree.body:
        if not isinstance(stmt, ast.ImportFrom) or not stmt.names or stmt.names[0].name != "*":
            continue
        origin = _resolve_from_module(module, stmt)
        if origin is None or project.resolve_module(origin) is not None:
            return ()
        origins.append(tuple(origin.split(".")))
    return tuple(origins)


def _classify_reference(
    name: str,
    attrs: tuple,
    bound: frozenset,
    local_imports: dict,
    module: ModuleInfo,
    owner: ClassInfo | None,
    project: ProjectIndex,
    seen: frozenset = frozenset(),
) -> tuple:
    """``(tag, source module)`` for a maximal ``Name``/``Attribute`` chain; both may be ``None``.

    Rests on external capability having to enter app code through a name the source mentions, so
    classifying every mention resolving outside the app suffices — provided `_ORIGIN_CAPABILITIES`
    names every origin that carries one.

    A locally bound root is not a mention: it holds what some expression here produced, and that is
    classified on its own. A module-level value is the same one scope up, except the producing
    expression sits elsewhere — hence ``source``, whose import-time code the caller folds in.
    """
    if name in local_imports:  # no symbol table names a function-local import; the statement does
        return _tagset(_origin_class((*local_imports[name], *attrs))), None
    if name == "self":
        if owner is None or not attrs:
            return frozenset(), None
        return _class_attr_services(owner, attrs[0], project, seen), None
    if name in bound:
        return frozenset(), None
    return _classify_chain(name, attrs, module, project, seen)


def _tagset(tag: str | None) -> frozenset:
    return frozenset() if tag is None else frozenset({tag})


@functools.cache
def _classify_chain(name: str, attrs: tuple, module: ModuleInfo, project: ProjectIndex, seen: frozenset) -> tuple:
    """Resolve a dotted chain against ``module`` and classify what it names.

    Keyed on the chain rather than the node: the same few chains (``vkt.Text``, ``np.array``,
    ``requests.get``) are mentioned over and over across an app's bodies, and resolution is the
    expensive half of classification.
    """
    if name not in _module_symbols(module):
        # neither imported nor defined at module level -> a builtin, a star-imported name, or a name
        # nothing can resolve
        if name in _PURE_BUILTINS:
            return frozenset(), None
        if name in _IMPURE_BUILTINS:
            return _tagset(_IMPURE_BUILTINS[name]), None
        origins = _star_import_origins(module, project)
        if not origins:
            return _tagset(_EXTERNAL_UNKNOWN), None
        # under several star imports the name could have come from any of them, so the first origin
        # carrying a capability decides
        tags = (_origin_class((*origin, name, *attrs)) for origin in origins)
        return _tagset(next((tag for tag in tags if tag is not None), None)), None
    res: Resolution = resolve_name(project, name, module)
    for attr in attrs:
        if res is None:
            break
        resolved = resolve_attr(project, res, attr)
        if resolved is None and isinstance(res, AppClass):
            # an attribute the class assigns rather than defines — an enum member, a class constant,
            # a client built in the class body — is attributed exactly as ``self.<attr>`` is
            return _class_attr_services(res.classinfo, attr, project, seen), None
        res = resolved
    if isinstance(res, External):
        return _tagset(_origin_class(res.origin)), None
    if res is None:
        # a module-level value is not unknown, it just needs its source classified; anything else
        # unresolvable — an unparseable module, a member that is not there — is
        source = _module_level_value_source(name, module, project)
        return (frozenset(), source) if source is not None else (_tagset(_EXTERNAL_UNKNOWN), None)
    return frozenset(), None  # app code: covered by reachability, not by this classification


class ClassInfo:
    """An app class resolved from source: its bases, MRO, and members, all AST-derived."""

    def __init__(self, project: ProjectIndex, classdef: ast.ClassDef, module: ModuleInfo) -> None:
        self.project = project
        self.classdef = classdef
        self.module = module
        self._mro: list | None = None

    @property
    def name(self) -> str:
        return self.classdef.name

    def _base_resolutions(self) -> list:
        return [resolve_ref_chain(self.project, b, self.module) for b in self.classdef.bases]

    def base_classinfos(self) -> list:
        return [r.classinfo for r in self._base_resolutions() if isinstance(r, AppClass)]

    def base_externals(self) -> list:
        return [r.origin for r in self._base_resolutions() if isinstance(r, External)]

    def mro(self) -> list:
        """This class followed by its in-app bases, depth-first, de-duplicated, cycle-guarded."""
        if self._mro is not None:
            return self._mro
        order: list = []
        seen: set = set()

        def visit(ci: ClassInfo) -> None:
            if id(ci.classdef) in seen:
                return
            seen.add(id(ci.classdef))
            order.append(ci)
            for base in ci.base_classinfos():
                visit(base)

        visit(self)
        self._mro = order
        return order

    def is_viktor_controller(self, _visited: set | None = None) -> bool:
        _visited = _visited if _visited is not None else set()
        if id(self.classdef) in _visited:
            return False
        _visited.add(id(self.classdef))
        for origin in self.base_externals():
            if origin and origin[0] == "viktor" and origin[-1] in _CONTROLLER_BASE_NAMES:
                return True
        return any(base.is_viktor_controller(_visited) for base in self.base_classinfos())

    def own_member(self, name: str) -> tuple | None:
        """``(node, kind)`` for a member defined directly in this class body, else ``None``.

        ``kind`` is ``'static'`` / ``'classmethod'`` / ``'property'`` / ``'method'`` for functions
        (from the decorator), or ``'class'`` for a nested class.
        """
        for stmt in self.classdef.body:
            if isinstance(stmt, _FuncDef) and stmt.name == name:
                return stmt, self._member_kind(stmt)
            if isinstance(stmt, ast.ClassDef) and stmt.name == name:
                return stmt, "class"
        return None

    def lookup_member(self, name: str) -> tuple | None:
        """``(node, defining_ClassInfo, kind)`` for ``name`` found up the in-app MRO, else ``None``."""
        for ci in self.mro():
            member = ci.own_member(name)
            if member is not None:
                node, kind = member
                return node, ci, kind
        return None

    def _member_kind(self, funcdef: ast.AST) -> str:
        symbols = _module_symbols(self.module)
        for dec in funcdef.decorator_list:
            # `@staticmethod` / `@classmethod` / `@property` are bare names, not calls; only honour
            # them when not shadowed by a module-level binding of the same name.
            if isinstance(dec, ast.Name) and dec.id not in symbols:
                if dec.id == "staticmethod":
                    return "static"
                if dec.id == "classmethod":
                    return "classmethod"
                if dec.id == "property":
                    return "property"
        return "method"

    def find_init(self) -> AppFunc | None:
        res = self.resolve_class_attr("__init__")
        return res if isinstance(res, AppFunc) else None

    def resolve_class_attr(self, name: str) -> Resolution:
        """Resolve a class-level attribute up the MRO to a ``App*``/``External`` result, or ``None``.

        Covers nested class / function defs *and* class-body assignments that alias another name
        (``model = TestModel``), resolving the aliased ref against its defining class's module.
        The ``model = SomeClass`` alias is how apps expose a ``self.model(params)`` factory.
        """
        for ci in self.mro():
            for stmt in ci.classdef.body:
                if isinstance(stmt, ast.ClassDef) and stmt.name == name:
                    return AppClass(self.project.classinfo(stmt, ci.module))
                if isinstance(stmt, _FuncDef) and stmt.name == name:
                    return AppFunc(stmt, ci.module, ci)
                if isinstance(stmt, (ast.Assign, ast.AnnAssign)):
                    targets = stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]
                    if isinstance(stmt.value, (ast.Name, ast.Attribute)) and any(
                        isinstance(t, ast.Name) and t.id == name for t in targets
                    ):
                        return resolve_ref_chain(self.project, stmt.value, ci.module)
        return None


# --- view discovery ----------------------------------------------------------


def iter_controllers(project: ProjectIndex) -> Iterator[ClassInfo]:
    """Yield a ``ClassInfo`` for every top-level ``ViktorController`` subclass in the app."""
    for module in project.modules.values():
        if module.tree is None:
            continue
        for stmt in module.tree.body:
            if isinstance(stmt, ast.ClassDef):
                ci = project.classinfo(stmt, module)
                if ci.is_viktor_controller():
                    yield ci


def _registered_entity_type_names(project: ProjectIndex) -> dict[int, str]:
    """Map ``id(controller ClassDef) -> the entity-type name the app registers it under``.

    An app registers a controller as an entity type by importing it into its root ``__init__.py``
    under the platform-facing name (``import FooController as Foo`` -> ``Foo``) -- that alias, not
    the class name, is the entity-type name.
    """
    names: dict[int, str] = {}
    for module in project.modules.values():
        # the root app package: a package module at the top of the dotted namespace (`app`).
        if not (module.is_package and module.tree is not None and "." not in module.dotted_name):
            continue
        for bound, binding in _module_symbols(module).items():
            res = resolve_binding(project, binding, module, frozenset())
            if isinstance(res, AppClass) and res.classinfo.is_viktor_controller():
                names.setdefault(id(res.classinfo.classdef), bound)
    return names


def _is_view(project: ProjectIndex, funcdef: ast.AST, module: ModuleInfo) -> bool:
    """Is ``funcdef`` a view? True when a decorator resolves to a ``viktor`` view class."""
    for dec in funcdef.decorator_list:
        target = dec.func if isinstance(dec, ast.Call) else dec
        res = resolve_ref_chain(project, target, module)
        if (
            isinstance(res, External)
            and res.origin
            and res.origin[0] == "viktor"
            and res.origin[-1] in _VIEW_DECORATOR_NAMES
        ):
            return True
    return False


def iter_views(project: ProjectIndex, controller: ClassInfo) -> list:
    """Yield ``(funcdef, defining_ClassInfo)`` per view, overrides winning."""
    found: dict = {}
    for ci in reversed(controller.mro()):  # base-first so a derived override replaces the base's
        for stmt in ci.classdef.body:
            if isinstance(stmt, _FuncDef) and _is_view(project, stmt, ci.module):
                found[stmt.name] = (stmt, ci)
    return list(found.values())


# --- static analyzer ----------------------------------------------------------


def _instance_binding(env: Env, name: str) -> _Instance | None:
    """The tracked ``_Instance`` a name holds in ``env``, or ``None`` if it holds anything else."""
    value = env.get(name)
    return value if isinstance(value, _Instance) else None


class _Instance:
    """A local bound to an app object built from params (the ``m = self.model(params)`` pattern).

    Tracks ``self.<attr>`` assignments seen while following ``__init__`` and methods:
    ``param_attrs`` maps each attribute to the params path it holds; ``nonparam_attrs`` holds
    attributes assigned a non-params value (reading them is not a dependency).
    """

    def __init__(self, cls: ClassInfo) -> None:
        self.cls = cls
        self.param_attrs: dict[str, ParamPath] = {}
        self.nonparam_attrs: set[str] = set()


# What an in-scope name is bound to during analysis: a params path or a tracked instance.
# The reserved _SELF key instead holds a {attr: ParamPath} map of `self.<attr>` bindings.
Env = dict[str, ParamPath | _Instance | dict]


class _Frame:
    """Per-function analysis context: what names/callees resolve against (source-only)."""

    def __init__(
        self,
        funcdef: ast.FunctionDef | ast.AsyncFunctionDef,
        module: ModuleInfo,
        owner: ClassInfo | None,
        project: ProjectIndex,
    ) -> None:
        self.funcdef = funcdef  # body this frame covers; keys the external-input sweep
        self.module = module  # module whose symbol table free names resolve against
        self.owner = owner  # controller/class this body belongs to, for `self.x`
        self.project = project
        self.instance: _Instance | None = None  # set when following an __init__/method to capture self.X
        self.local_defs, self.assigned_names, self.single_assignment_calls = _derive_locals(funcdef)


class _Analyzer:
    """Walks a view's AST, recording which params paths it depends on.

    Abstract interpretation over an ``env`` mapping each in-scope name to what it holds:

    - a ``ParamPath`` tuple — the name aliases ``params`` at that path (the root ``params`` is ``()``);
    - an ``_Instance`` — an app object built from params;
    - absent — untrackable, so any access through it escapes.

    The reserved ``_SELF`` key holds ``{attr: ParamPath}`` so ``self.x`` resolves inside a followed
    method. Every resolved params access ends at ``_leaf(path)`` (a specific leaf is read) or
    ``_escape(path)`` (its whole subtree is a dependency); anything the analyzer cannot resolve
    escapes rather than being dropped — that is what keeps the result sound. Calls that pass params
    are followed into the callee's source, with ``_enter`` guarding against cycles and the depth cap.
    """

    def __init__(self, result: _ViewParamDependency, project: ProjectIndex) -> None:
        self.result = result  # swapped for a throwaway sink while detection-only scanning
        self.project = project
        self._active: set = set()  # keys of functions currently on the params-analysis stack
        self._walked: set = set()  # keys of function bodies already walked in this view
        self._detect_depth = 0  # nesting depth of detection-only scans, capped at `_MAX_DEPTH`
        self._platform_services: set = set()  # category tags: subset of `_PLATFORM_SERVICES` values
        self._external_services: set = set()  # category tags, `_EXTERNAL_UNKNOWN` where it gave up

    @contextlib.contextmanager
    def _enter(self, key: Any) -> Generator[bool]:
        """Guard one interprocedural descent, escalating `external_services` when it is refused.

        A refused descent means reachable code went unwalked, so escalation belongs in the guard:
        every give-up site inherits it and a new one cannot forget. A cycle on an already-swept body
        escalates needlessly, which is the cheaper error to make.
        """
        if key in self._active or len(self._active) >= _MAX_DEPTH:
            self._external_escalate()
            yield False
            return
        self._active.add(key)
        try:
            yield True
        finally:
            self._active.discard(key)

    @contextlib.contextmanager
    def _params_sink(self) -> Generator[None]:
        """Discard every params recording made inside the block.

        For a walk the params dimension has no stake in, an empty ``env`` is not enough isolation on
        its own: a recording can be env-independent — the closure depth cap escapes the params
        *root* — so the result object is swapped for a throwaway and dropped on exit. That makes such
        a walk structurally unable to widen a view's contract, rather than merely unlikely to.
        """
        params_result, self.result = self.result, _ViewParamDependency()
        try:
            yield
        finally:
            self.result = params_result

    # -- recording ------------------------------------------------------------

    def _mark_walked(self, funcdef: ast.AST) -> None:
        self._walked.add(("node", id(funcdef)))

    def _leaf(self, path: ParamPath) -> None:
        if not path:
            # A bare read of the whole params object as a *value* (e.g. ``if not params:``).
            return
        self.result.paths.add(path)

    def _escape(self, path: ParamPath) -> None:
        if not path:
            self.result.fell_back_to_everything = True
        else:
            self.result.escaped_nodes.add(path)

    def _escape_bindings(self, bindings: dict) -> None:
        for path in set(bindings.values()):
            self._escape(path)

    def _visit_get_default(self, node: ast.AST, env: Env, frame: _Frame) -> None:
        """Visit the extra args of a ``x.get('literal', default)`` call.

        ``_params_path`` resolves such a call to the key's path from ``args[0]`` alone, so a
        caller that consumes that path never visits the default expression — which is always
        evaluated and may read params. Only ``.get`` calls resolve to a path, so this is a no-op
        for anything else.
        """
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "get":
            # the default is a fallback *value* handed back wholesale -> opaque (a bare root
            # `params` default escalates to `*` rather than being dropped by `_leaf(())`).
            for extra in node.args[1:]:
                self._visit(extra, env, frame, opaque=True)
            for kw in node.keywords:
                self._visit(kw.value, env, frame, opaque=True)

    # -- statements -----------------------------------------------------------

    def walk_body(self, stmts: list, env: Env, frame: _Frame) -> None:
        self._sweep_external_services(frame)
        for stmt in stmts:
            self._walk_stmt(stmt, env, frame)

    # -- external services ----------------------------------------------------

    def _external_escalate(self) -> None:
        """Record that reachable code could not be classified, so a service may be reached.

        The service counterpart of `_escape`: wherever the analyzer gives up on code a view reaches,
        it flags here rather than returning silently. Both dimensions take the tag — unseen code
        could have called the platform as easily as anything else, and each dimension gates alone.
        """
        self._external_services.add(_EXTERNAL_UNKNOWN)
        self._platform_services.add(_EXTERNAL_UNKNOWN)

    def _sweep_external_services(self, frame: _Frame) -> None:
        """Fold in the service tags of ``frame``'s whole body (see `_body_external_services`)."""
        self._external_services |= _body_external_services(frame.funcdef, frame.module, frame.owner, self.project)

    def _walk_stmt(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:  # noqa: C901
        if isinstance(stmt, ast.Assign):
            self._handle_assign(stmt.targets, stmt.value, env, frame)
        elif isinstance(stmt, ast.AnnAssign) and stmt.value is not None:
            self._handle_assign([stmt.target], stmt.value, env, frame)
        elif isinstance(stmt, ast.AugAssign):
            self._visit(stmt.value, env, frame)
            tp = _params_path(stmt.target, env)
            if tp is not None:
                self._leaf(tp)
            else:
                self._visit_store_target(stmt.target, env, frame)
        elif isinstance(stmt, ast.Return):
            if stmt.value is not None:
                self._visit(stmt.value, env, frame, opaque=True)
        elif isinstance(stmt, ast.Expr):
            self._visit(stmt.value, env, frame)
        elif isinstance(stmt, ast.If):
            self._handle_conditional(stmt, env, frame)
        elif isinstance(stmt, ast.While):
            self._handle_while(stmt, env, frame)
        elif isinstance(stmt, (ast.For, ast.AsyncFor)):
            self._handle_for(stmt, env, frame)
        elif isinstance(stmt, (ast.With, ast.AsyncWith)):
            self._handle_with(stmt, env, frame)
        elif isinstance(stmt, ast.Try):
            self._handle_try(stmt, env, frame)
        elif isinstance(stmt, ast.Match):
            self._handle_match(stmt, env, frame)
        elif isinstance(stmt, _FuncDef):
            # a nested function may run and read params via closure -> analyse it eagerly
            # (also followed at its call site for argument-passed params).
            for dec in stmt.decorator_list:  # decorators are evaluated at def time in this scope
                self._visit(dec, env, frame)
            self._analyze_closure(stmt, env, frame)
        else:
            # fail-safe: recurse into children so params reads are recorded (never dropped)
            # for any statement type not modelled above (assert, raise, del, ...).
            for child in ast.iter_child_nodes(stmt):
                if isinstance(child, ast.expr):
                    self._visit(child, env, frame)
                elif isinstance(child, ast.stmt):
                    self._walk_stmt(child, env, frame)

    def _visit_store_target(self, target: ast.AST, env: Env, frame: _Frame) -> None:
        """Record params reads in the *load* sub-expressions of an assignment target.

        A bare ``Name`` store is not a read (aliasing is handled by the caller). For a
        subscript / attribute target the base being indexed and the subscript key are evaluated,
        so a params ref there is a real dependency; writing *into* a params path depends on it
        (consistent with the augassign-target rule).
        """
        if isinstance(target, ast.Name) or _is_self_attr(target):
            # a bare-name store isn't a read; a `self.<attr> =` store is handled by the instance
            # branch (its only load part is `self`, which carries no params).
            return
        if isinstance(target, (ast.Tuple, ast.List)):
            for elt in target.elts:
                self._visit_store_target(elt.value if isinstance(elt, ast.Starred) else elt, env, frame)
            return
        tp = _params_path(target, env)
        if tp is not None:  # e.g. `params.section = ...` -> depend on the written path
            self._leaf(tp)
            return
        if isinstance(target, ast.Subscript):
            base = _params_path(target.value, env)
            if base is not None:  # `params.x[k] = ...` -> writing into the subtree depends on it
                self._escape(base)
                self._visit_get_default(target.value, env, frame)  # a `.get()` base still evaluates its default
            else:
                self._visit(target.value, env, frame)
            self._visit(target.slice, env, frame)
        elif isinstance(target, ast.Attribute):
            base = _params_path(target.value, env)
            if base is not None:
                self._escape(base)
                self._visit_get_default(target.value, env, frame)  # a `.get()` base still evaluates its default
            else:
                self._visit(target.value, env, frame)
        else:  # pragma: no cover - store targets are only Name/Attribute/Subscript/Tuple/List, all handled above
            return

    def _handle_assign(self, targets: list, value: ast.AST, env: Env, frame: _Frame) -> None:
        for t in targets:  # params reads embedded in a subscript/attribute target are dependencies
            self._visit_store_target(t, env, frame)
        value_path = _params_path(value, env)
        if value_path is not None:
            self._visit_get_default(value, env, frame)  # a `.get(k, default)` still evaluates its default

        # `self.<attr> = ...` while following an __init__/method: record what the attribute holds.
        if frame.instance is not None and len(targets) == 1 and _is_self_attr(targets[0]):
            attr = targets[0].attr
            if value_path is not None:
                # Branch bodies share one `_Instance` (it lives on the frame, not in `env`, so
                # `_merge_into` never reconciles it). A conditional `self.x = params.a` / `self.x =
                # params.b` would otherwise keep only the last-walked path; escape any *different*
                # path a sibling branch already recorded so it is not clobbered and lost.
                prev = frame.instance.param_attrs.get(attr)
                if prev is not None and prev != value_path:
                    self._escape(prev)  # over-approximate, never under
                frame.instance.param_attrs[attr] = value_path
            else:
                self._visit(value, env, frame)  # record any params read while computing the value
                frame.instance.nonparam_attrs.add(attr)
            return

        if value_path is not None:
            if targets and all(isinstance(t, ast.Name) for t in targets):
                for t in targets:  # alias binding(s) -- no read recorded
                    env[t.id] = value_path
            else:  # unpacking / stored into attr/subscript -> whole subtree consumed
                self._escape(value_path)
            return

        # `x = m` where m is a tracked instance -> alias the instance (don't escape it).
        inst = _instance_binding(env, value.id) if isinstance(value, ast.Name) else None
        if inst is not None:
            if len(targets) == 1 and isinstance(targets[0], ast.Name):
                env[targets[0].id] = inst
            else:
                self._escape_bindings(inst.param_attrs)
            return

        # `m = SomeAppClass(params...)` -> track the instance so its methods/attrs resolve.
        if isinstance(value, ast.Call) and len(targets) == 1 and isinstance(targets[0], ast.Name):
            instance = self._maybe_build_instance(value, env, frame)
            if instance is not None:
                env[targets[0].id] = instance
                return

        # the value is bound to the target name(s) wholesale -> opaque, so a bare `params` RHS
        # (`x = params or {}`) escalates to the root rather than being dropped.
        self._visit(value, env, frame, opaque=True)
        for t in targets:
            for name in _target_names(t):
                env.pop(name, None)

    def _handle_conditional(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:
        self._visit(stmt.test, env, frame)
        body_env = dict(env)
        self.walk_body(stmt.body, body_env, frame)
        else_env = dict(env)
        self.walk_body(stmt.orelse, else_env, frame)
        # branches are conditional -> merge alias changes so a rebind in one branch can't
        # leave a stale binding that under-tracks the other branch's path.
        self._merge_into(env, [body_env, else_env])

    def _handle_while(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:
        def run_pass(work: Env) -> None:
            self._visit(stmt.test, work, frame)  # the test is re-evaluated every iteration
            self.walk_body(stmt.body, work, frame)

        self._walk_loop(env, run_pass)
        self.walk_body(stmt.orelse, dict(env), frame)

    def _handle_for(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:
        ip = _params_path(stmt.iter, env)
        if ip is not None:
            self._leaf(ip)  # iterating the list is itself a dependency on the list node
            self._visit_get_default(stmt.iter, env, frame)
        else:
            self._visit(stmt.iter, env, frame)
        targets = _target_names(stmt.target)

        def run_pass(work: Env) -> None:
            # the loop element is untracked (we stop at the list node), so unbind the targets.
            for name in targets:
                work.pop(name, None)
            self.walk_body(stmt.body, work, frame)

        self._walk_loop(env, run_pass)
        self.walk_body(stmt.orelse, dict(env), frame)

    def _walk_loop(self, env: Env, run_pass: callable) -> None:
        """Analyse a loop body to a fixpoint over its loop-carried bindings.

        A name bound near the bottom of a loop is live at the top on the 2nd+ iteration, so a
        single pass under-tracks a read of it (``x`` below reads ``params.secret`` on re-entry)::

            for _ in items:
                use(x)  # reads x — bound only on the previous iteration
                x = params.secret

        So we re-walk the body against the merged loop-head env (pre-loop *or* post-body) until
        it stops changing. Reads only accumulate, so extra passes can only add dependencies, and
        a loop with no carried binding converges in one pass (no cost over a single walk). If it
        has not converged within ``_LOOP_PASSES`` we escape every binding the loop *changed* —
        unchanged ones (notably ``params`` at the root) were already read on the first pass.
        """
        pre_loop = dict(env)
        for _ in range(_LOOP_PASSES):
            work = dict(env)
            run_pass(work)
            before = dict(env)
            # the loop head could hold the pre-loop value (0 iterations) or the post-body one.
            self._merge_into(env, [work])
            if env == before:
                return  # env stabilised -> fixpoint reached
        for name, value in list(env.items()):
            if name == _SELF or pre_loop.get(name) == value:
                continue
            if isinstance(value, tuple):
                self._escape(value)
            elif isinstance(value, _Instance):  # pragma: no branch - env values are only ParamPath/_Instance
                self._escape_bindings(value.param_attrs)

    def _handle_with(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:
        # a `with` body always runs (no branching), so items bind into the same env.
        for item in stmt.items:
            self._visit(item.context_expr, env, frame)
            if isinstance(item.optional_vars, ast.Name):
                p = _params_path(item.context_expr, env)
                if p is not None:  # `with params.x as y:` -> y aliases params.x
                    env[item.optional_vars.id] = p
                else:
                    env.pop(item.optional_vars.id, None)
        self.walk_body(stmt.body, env, frame)

    def _handle_try(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:
        body_env = dict(env)
        self.walk_body(stmt.body, body_env, frame)
        branch_envs = [body_env]
        for handler in stmt.handlers:
            handler_env = dict(env)
            if handler.type is not None:  # `except <type-expr>:` may read params
                self._visit(handler.type, handler_env, frame)
            self.walk_body(handler.body, handler_env, frame)
            branch_envs.append(handler_env)
        else_env = dict(body_env)  # else runs only after the body succeeded
        self.walk_body(stmt.orelse, else_env, frame)
        branch_envs.append(else_env)
        self._merge_into(env, branch_envs)
        self.walk_body(stmt.finalbody, env, frame)  # finally always runs, in sequence

    def _handle_match(self, stmt: ast.AST, env: Env, frame: _Frame) -> None:
        # Each case is a conditional branch, like an `if`/`elif` chain. Handling it explicitly
        # is necessary as well as consistent: the fail-safe's `iter_child_nodes` would stop at
        # the `match_case` wrapper (neither stmt nor expr), dropping the case bodies' reads.
        self._visit(stmt.subject, env, frame)
        branch_envs = []
        for case in stmt.cases:
            case_env = dict(env)
            self._visit_pattern(case.pattern, case_env, frame)  # value/mapping/class patterns may read params
            if case.guard is not None:
                self._visit(case.guard, case_env, frame)
            self.walk_body(case.body, case_env, frame)
            branch_envs.append(case_env)
        self._merge_into(env, branch_envs)

    def _visit_pattern(self, pattern: ast.AST, env: Env, frame: _Frame) -> None:
        """Visit the expressions embedded in a ``match`` case pattern.

        Value patterns (``case params.x:``), mapping-pattern keys (``case {params.k: v}:``) and a
        class pattern's class reference are evaluated at match time, so a params read there is a
        real dependency. Capture names bind sub-values of the subject, not params, so they need no
        handling. Sub-patterns are walked recursively.
        """
        if isinstance(pattern, ast.MatchValue):
            self._visit(pattern.value, env, frame)
        elif isinstance(pattern, ast.MatchMapping):
            for key in pattern.keys:
                self._visit(key, env, frame)
            for sub in pattern.patterns:
                self._visit_pattern(sub, env, frame)
        elif isinstance(pattern, ast.MatchClass):
            self._visit(pattern.cls, env, frame)
            for sub in (*pattern.patterns, *pattern.kwd_patterns):
                self._visit_pattern(sub, env, frame)
        elif isinstance(pattern, (ast.MatchSequence, ast.MatchOr)):
            for sub in pattern.patterns:
                self._visit_pattern(sub, env, frame)
        elif isinstance(pattern, ast.MatchAs) and pattern.pattern is not None:
            self._visit_pattern(pattern.pattern, env, frame)
        elif isinstance(pattern, ast.MatchStar):  # pragma: no cover - `*rest` captures, no embedded expr
            return

    def _merge_into(self, env: Env, branch_envs: list) -> None:
        """Merge conditionally-taken branch envs back into ``env``.

        A name bound to the *same* single params path across every branch keeps that binding;
        one bound to differing paths (or to a mix of paths/instances) is ambiguous — escape
        every candidate and unbind it, so a later use can never under-track an alternate branch.
        """
        pre = dict(env)
        names = set(pre)
        for branch in branch_envs:
            names |= set(branch)
        for name in names:
            if name == _SELF:  # reserved key -> leave as-is
                continue
            seen = [src[name] for src in (pre, *branch_envs) if name in src]
            tuples = {v for v in seen if isinstance(v, tuple)}
            instances = [v for v in seen if isinstance(v, _Instance)]
            if len(tuples) == 1 and not instances:
                env[name] = next(iter(tuples))
            elif not tuples and len(set(map(id, instances))) == 1:
                env[name] = instances[0]
            else:  # ambiguous / mixed -> fail safe: escape every candidate, unbind
                for path in tuples:
                    self._escape(path)
                for inst in instances:
                    self._escape_bindings(inst.param_attrs)
                env.pop(name, None)

    def _analyze_closure(self, node: ast.AST, env: Env, frame: _Frame) -> None:
        """Analyse a nested function / lambda ``node`` with the enclosing env (closure capture).

        The callable's own parameters shadow the closure, so they're removed from the env —
        this both catches params read via closure and avoids false positives from a parameter
        that happens to be named ``params``.
        """
        args = node.args
        # default-arg expressions are evaluated in the *enclosing* scope at def time (before the
        # params shadow them) and are captured wholesale into the callable -> opaque.
        for default in (*args.defaults, *args.kw_defaults):
            if default is not None:
                self._visit(default, env, frame, opaque=True)
        shadowed = {a.arg for a in (args.posonlyargs + args.args + args.kwonlyargs)}
        if args.vararg:
            shadowed.add(args.vararg.arg)
        if args.kwarg:
            shadowed.add(args.kwarg.arg)
        closure_env = {k: v for k, v in env.items() if k not in shadowed}
        with self._enter(("closure", id(node))) as entered:
            if not entered:
                # depth cap / cycle: we can't analyse the body, but a closure captures the whole
                # enclosing scope (including `params`), so it may read any path. Escalate to the
                # entire params root rather than dropping the read (over-approximate, never under).
                self._escape(())
                return
            if isinstance(node, _FuncDef):
                self._mark_walked(node)  # a local def is also a call target -> no re-walk to scan it
                self.walk_body(node.body, closure_env, frame)
                # `global`/`nonlocal` names bind an *outer* scope, so an alias written through one
                # -- `nonlocal acc; acc = params.secret` -- records nothing here (it is an alias,
                # not a read) yet survives the closure and is read outside it. closure_env is a copy
                # that never flows back, so escape whatever params such a name ends up holding; sound
                # no matter when (or whether) the closure runs. Reads *inside* it are caught above.
                for name in _writeback_names(node):
                    value = closure_env.get(name)
                    if isinstance(value, tuple):
                        self._escape(value)
                    elif isinstance(value, _Instance):
                        self._escape_bindings(value.param_attrs)
            else:  # lambda: a single expression -> no statements, so no global/nonlocal write-back
                self._visit(node.body, closure_env, frame)

    # -- expressions ----------------------------------------------------------

    def _visit(self, node: ast.AST, env: Env, frame: _Frame, opaque: bool = False) -> None:  # noqa: C901
        """Handle an expression whose value is consumed (``opaque`` = taken wholesale)."""
        p = _params_path(node, env)
        if p is not None:
            if opaque:
                self._escape(p)
            else:
                self._leaf(p)
            self._visit_get_default(node, env, frame)  # `.get(k, default)` still evaluates its default
            return

        # a bare tracked instance consumed as a value (passed to a call, returned, stored) -> we
        # can no longer follow it, so escape everything it carries from params.
        inst = _instance_binding(env, node.id) if isinstance(node, ast.Name) else None
        if inst is not None:
            self._escape_bindings(inst.param_attrs)
            return

        if isinstance(node, ast.NamedExpr):  # walrus (target := value)
            # a walrus target is always a plain Name (the grammar forbids attribute/subscript/tuple)
            ref = _params_path(node.value, env)
            if ref is not None:
                env[node.target.id] = ref  # alias so later uses of the target resolve
            else:
                env.pop(node.target.id, None)
            self._visit(node.value, env, frame, opaque=opaque)  # the value is also consumed in place
        elif isinstance(node, ast.Lambda):
            self._analyze_closure(node, env, frame)  # may run later, closes over env
        elif isinstance(node, ast.Call):
            self._visit_call(node, env, frame)
        elif isinstance(node, ast.Subscript):
            base = _params_path(node.value, env)
            if base is not None:
                # list index (``loads[0]``/``loads[i]``) or dynamic dict key on a params ref: we
                # can't name the element, so the whole node is the dependency.
                self._escape(base)
                self._visit_get_default(node.value, env, frame)  # a `.get()` base still evaluates its default
            else:
                self._visit(node.value, env, frame)
            self._visit(node.slice, env, frame)
        elif isinstance(node, ast.Attribute):
            inst = _instance_binding(env, node.value.id) if isinstance(node.value, ast.Name) else None
            if inst is not None:
                self._read_instance_attr(inst, node.attr, env)
                return
            base = _params_path(node.value, env)
            if base is not None:  # bulk method / non-extendable attr on a params ref
                self._escape(base)
                self._visit_get_default(node.value, env, frame)  # a `.get()` base still evaluates its default
            else:
                self._visit(node.value, env, frame)
        elif isinstance(node, ast.BinOp):
            # the result can carry params wholesale (e.g. `params + other`) -> propagate opaque
            self._visit(node.left, env, frame, opaque=opaque)
            self._visit(node.right, env, frame, opaque=opaque)
        elif isinstance(node, ast.BoolOp):
            # `a or b` can short-circuit to an operand as-is -> propagate opaque so a returned
            # bare `params` escalates to the root rather than being dropped by `_leaf(())`.
            for value in node.values:
                self._visit(value, env, frame, opaque=opaque)
        elif isinstance(node, ast.UnaryOp):
            self._visit(node.operand, env, frame)
        elif isinstance(node, ast.Compare):
            self._visit(node.left, env, frame)
            for comparator in node.comparators:
                self._visit(comparator, env, frame)
        elif isinstance(node, ast.IfExp):
            self._visit(node.test, env, frame)
            self._visit(node.body, env, frame, opaque=opaque)
            self._visit(node.orelse, env, frame, opaque=opaque)
        elif isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            for elt in node.elts:
                # stored into a container -> opaque (a bare ref escapes to its subtree)
                self._visit(elt.value if isinstance(elt, ast.Starred) else elt, env, frame, opaque=True)
        elif isinstance(node, ast.Dict):
            for key, value in zip(node.keys, node.values, strict=True):
                if key is None:  # {**mapping}
                    self._visit(value, env, frame, opaque=True)
                else:
                    self._visit(key, env, frame)
                    self._visit(value, env, frame, opaque=True)
        elif isinstance(node, ast.Starred):  # pragma: no cover - every syntactic Starred is unwrapped
            # by its container/call/subscript before recursion, so a bare Starred never reaches here;
            # kept as a defensive net that escapes the value's subtree if one ever does.
            self._visit(node.value, env, frame, opaque=True)
        elif isinstance(node, ast.JoinedStr):
            for value in node.values:
                self._visit(value, env, frame)
        elif isinstance(node, ast.FormattedValue):
            # `f"{x}"` calls `format(x)`/`str(x)`, which deep-reads every value under `x` -> opaque,
            # so a bare-root `f"{params}"` escalates to `*` (consistent with `str(params)`) instead
            # of being dropped by `_leaf(())`. Non-root refs are unchanged: a leaf and a subtree
            # escape emit the same path.
            self._visit(node.value, env, frame, opaque=True)
            if node.format_spec is not None:  # `f"{x:{params.width}}"` -> the spec is evaluated too
                self._visit(node.format_spec, env, frame)
        elif isinstance(node, (ast.ListComp, ast.SetComp, ast.GeneratorExp, ast.DictComp)):
            self._visit_comprehension(node, env, frame)
        elif isinstance(node, ast.Await):
            self._visit(node.value, env, frame, opaque=opaque)
        elif isinstance(node, (ast.Yield, ast.YieldFrom)):
            # a yielded value is handed out wholesale, exactly like a return -> opaque
            if node.value is not None:
                self._visit(node.value, env, frame, opaque=True)
        else:
            # fail-safe: recurse into every child expression so params reads are still recorded
            # (rather than silently dropped) for any expression type not modelled above.
            for child in ast.iter_child_nodes(node):
                if isinstance(child, ast.expr):
                    self._visit(child, env, frame)

    def _visit_comprehension(self, node: ast.AST, env: Env, frame: _Frame) -> None:
        env2 = dict(env)
        for gen in node.generators:
            ip = _params_path(gen.iter, env2)
            if ip is not None:
                self._leaf(ip)
                self._visit_get_default(gen.iter, env2, frame)
            else:
                self._visit(gen.iter, env2, frame)
            # the element is untracked (we stop at the list node), so unbind the target names.
            for name in _target_names(gen.target):
                env2.pop(name, None)
            for cond in gen.ifs:
                self._visit(cond, env2, frame)
        # A comprehension always builds a container holding its element(s), so the element is
        # "stored into a container" -> opaque, exactly like a List/Set/Dict literal. Without
        # this, a bare `params` element (`[params for _ in ...]`) hits `_leaf(())` and the
        # whole-params dependency is silently dropped instead of escalating to `*`.
        if isinstance(node, ast.DictComp):
            self._visit(node.key, env2, frame)
            self._visit(node.value, env2, frame, opaque=True)
        else:
            self._visit(node.elt, env2, frame, opaque=True)

    def _detect_platform_services(self, func: ast.AST, frame: _Frame) -> None:
        """Route every platform-service signal a call carries, from one resolution of its callee.

        - a viktor ``API``/``Storage`` client construction -> record its tag. Any construction counts
          (we don't inspect how the client is used), matched by *resolved* origin so a renamed import
          is caught too;
        - an app-class construction -> scan its ``__init__``, which runs right here. (Only reached for
          a construction the params pass does not track itself: a tracked one already walked it.)
        - ``obj.method(...)`` whose chain does not resolve -> try to type the receiver instead.

        Only ``Name``/``Attribute`` callees can name a class, so anything else carries no signal.
        """
        if not isinstance(func, (ast.Name, ast.Attribute)):
            return
        res = resolve_ref_chain(self.project, func, frame.module)
        if isinstance(res, External):
            tag = _platform_service_tag(res.origin)
            if tag is not None:
                self._platform_services.add(tag)
        elif isinstance(res, AppClass):
            init = res.classinfo.find_init()
            if init is not None:
                self._scan_callee_detected(init)  # constructing the object runs `__init__`
        elif res is None and isinstance(func, ast.Attribute):
            self._scan_receiver_method(func, frame)

    def _scan_receiver_method(self, func: ast.Attribute, frame: _Frame) -> None:
        """Scan the method ``obj.method`` names when ``obj`` is an app object params-following misses.

        The params pass tracks an instance only when it is bound to a name *and* its class has an
        in-app ``__init__``; outside that, ``obj.method()`` is an unfollowable callee, so a client
        constructed inside that method would go unseen. Both remaining shapes are typed here from the
        construction itself — ``Model().load()`` (constructed in place) and ``m = Model(); m.load()``
        on a class with no in-app ``__init__`` — so this can only follow a call the source really
        makes. A receiver that is anything else (a parameter, a re-bound name, a returned object)
        stays untyped and unscanned.
        """
        recv = func.value
        if isinstance(recv, ast.Name):
            recv = frame.single_assignment_calls.get(recv.id)
        if not isinstance(recv, ast.Call) or not isinstance(recv.func, (ast.Name, ast.Attribute)):
            return
        res = resolve_ref_chain(self.project, recv.func, frame.module)
        if not isinstance(res, AppClass):
            return
        found = res.classinfo.lookup_member(func.attr)
        if found is None or not isinstance(found[0], _FuncDef):
            return  # set at runtime, a nested class, or not a member at all -> nothing to scan
        fnode, owner_ci, _ = found
        self._scan_callee_detected(AppFunc(fnode, owner_ci.module, owner_ci))

    def _visit_call(self, node: ast.AST, env: Env, frame: _Frame) -> None:  # noqa: C901
        func = node.func

        # Platform-service detection runs before the params branches below claim the node: it has to
        # see method calls too (`m.method()`), and several of those branches return early.
        self._detect_platform_services(func, frame)

        # method calls that carry params through `self` rather than through arguments:
        #   m.method(...)   where m is a tracked instance
        #   self.method(...) while following one of that instance's methods
        if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name):
            holder = _instance_binding(env, func.value.id)
            if holder is not None:
                self._follow_instance_method(holder, func.attr, node, env, frame)
                return
            if func.value.id == "self" and isinstance(env.get(_SELF), dict) and frame.instance is not None:
                found = frame.owner.lookup_member(func.attr) if frame.owner is not None else None
                if found is not None and isinstance(found[0], _FuncDef):
                    fnode, owner_ci, _ = found
                    self._follow_method(fnode, owner_ci, node, env, frame.instance, env[_SELF])
                else:
                    self._escape_bindings(env[_SELF])  # self.method() not followable
                self._visit_unbound_args(node, env, frame)
                return

        # method call on a params ref: non-literal .get(), bulk read, or unknown method. A literal
        # `params.x.get('k')` is a clean reference resolved upstream by `_params_path`, so anything
        # reaching here is unnameable -> the whole node escapes. The method is unfollowable, so its
        # arguments are handled like an unfollowable callee's: a params-rooted one escapes its
        # subtree, a non-ref one is visited for embedded reads. (params values can be lists/Munch —
        # `params.rows.sort(key=params.cmp)` — so keywords are visited too, not just positionals.)
        if isinstance(func, ast.Attribute):
            base = _params_path(func.value, env)
            if base is not None:
                self._escape(base)
                self._visit_get_default(func.value, env, frame)  # a `.get()` base still evaluates its default
                for arg in node.args:
                    self._visit(arg, env, frame)
                for kw in node.keywords:
                    kp = _params_path(kw.value, env)
                    if kp is None:
                        self._visit(kw.value, env, frame)  # non-ref kwarg -> record any embedded params reads
                    else:
                        self._visit_get_default(kw.value, env, frame)  # a `.get()` kwarg still evaluates its default
                        self._escape(kp)  # params ref / **-splat into an unfollowable method -> subtree escapes
                return

        # shallow builtins (hasattr/len/isinstance/...): a params-rooted arg is a leaf
        # dependency on that node, not its subtree — tighter than escaping it.
        if isinstance(func, ast.Name) and self._is_shallow_builtin(func.id, env, frame):
            self._visit_shallow_builtin(func.id, node, env, frame)
            return

        callee, offset = self._resolve_callee(func, frame)
        if offset == 1 and node.args and isinstance(node.args[0], ast.Name) and node.args[0].id == "self":
            offset = 0  # self passed explicitly (view-to-view call through the View wrapper)

        # Visit the callee expression too -- neither `_resolve_callee` nor the arg loop looks at it,
        # yet it can read params (`build(params.x).run()`, `make(params.y)(params.x)`). A bare-ref
        # receiver was consumed by branch 2, so `func.value` here never resolves to a params path.
        if isinstance(func, ast.Attribute):
            self._visit(func.value, env, frame)  # method call: the `.attr` selects, the receiver reads
        elif not isinstance(func, ast.Name):
            self._visit(func, env, frame, opaque=True)  # a call/other callee expr is consumed wholesale

        for i, arg in enumerate(node.args):
            if isinstance(arg, ast.Starred):
                self._visit(arg.value, env, frame, opaque=True)
                continue
            ap = _params_path(arg, env)
            if ap is None:
                self._visit(arg, env, frame)
                continue
            self._visit_get_default(arg, env, frame)  # a `.get(k, default)` arg still evaluates its default
            if callee is not None:
                self._interproc(callee, offset, "pos", i, ap)
            else:
                self._escape(ap)  # unfollowable callee -> the arg's subtree escapes
        for kw in node.keywords:
            kp = _params_path(kw.value, env)
            if kp is None:
                self._visit(kw.value, env, frame)
                continue
            self._visit_get_default(kw.value, env, frame)
            if kw.arg is None:  # **ref
                self._escape(kp)  # params ref splatted as **kwargs
            elif callee is not None:
                self._interproc(callee, offset, "kw", kw.arg, kp)
            else:
                self._escape(kp)  # unfollowable callee -> the arg's subtree escapes

        # A resolved app callee may construct a service client in its body -> scan it.
        if callee is not None:
            self._scan_callee_detected(callee)

    def _is_shallow_builtin(self, name: str, env: Env, frame: _Frame) -> bool:
        """True iff ``name`` is an allowlisted shallow builtin and not shadowed here."""
        if name not in _SHALLOW_BUILTINS or name in env or name in frame.assigned_names:
            return False  # not allowlisted, or shadowed by a local binding / def
        return name not in _module_symbols(frame.module)  # not overridden at module level

    def _visit_shallow_builtin(self, name: str, node: ast.AST, env: Env, frame: _Frame) -> None:
        args = node.args
        if name == "hasattr" and args:
            base = _params_path(args[0], env)
            if base is not None:
                attr = _literal_str_arg(args[1:2])  # hasattr(node, 'field') pins the exact child
                self._leaf((*base, attr) if attr is not None else base)
                self._visit_get_default(args[0], env, frame)
            else:
                self._visit(args[0], env, frame)
            for arg in args[1:]:  # the attr-name expr (when non-literal) is a plain value
                self._visit(arg, env, frame)
            return
        # No keyword handling: every allowlisted shallow builtin is positional-only, so a params
        # read can only reach here as a positional argument.
        for arg in args:
            if isinstance(arg, ast.Starred):  # pragma: no cover - splatting a params value into a
                # one/two-arg shallow builtin isn't written in practice; kept so the value's subtree
                # escapes (and so a bare Starred never falls through to `_visit`).
                self._visit(arg.value, env, frame, opaque=True)
                continue
            base = _params_path(arg, env)
            if base is not None:
                self._leaf(base)  # shallow inspection of this node — a leaf, not its subtree
                self._visit_get_default(arg, env, frame)
            else:
                self._visit(arg, env, frame)

    # -- interprocedural ------------------------------------------------------

    def _resolve_callee(self, func_node: ast.AST, frame: _Frame) -> tuple:
        """Resolve a call target to ``(AppFunc_or_None, arg_offset)``.

        A ``None`` callee means the target is unfollowable (unresolvable name, stdlib / SDK /
        third-party, class, builtin, ...) and the caller escapes the params-rooted args.
        """
        if isinstance(func_node, ast.Name):
            name = func_node.id
            if name in frame.local_defs:  # a nested def keeps the caller's module + owner (closure)
                return AppFunc(frame.local_defs[name], frame.module, frame.owner), 0
            res = resolve_name(self.project, name, frame.module)
            return (res if isinstance(res, AppFunc) else None), 0
        if isinstance(func_node, ast.Attribute) and isinstance(func_node.value, ast.Name):
            base_name = func_node.value.id
            if base_name == "self":
                if frame.owner is None:
                    return None, 1
                found = frame.owner.lookup_member(func_node.attr)
                if found is None or not isinstance(found[0], _FuncDef):
                    return None, 1
                fnode, owner_ci, kind = found
                # A @staticmethod accessed via self has no implicit first arg -> offset 0.
                # (A view-decorated method's body IS the view function in source — no wrapper to
                # unwrap; it resolves as a normal method here, offset 1.)
                return AppFunc(fnode, owner_ci.module, owner_ci), (0 if kind == "static" else 1)
            base = resolve_name(self.project, base_name, frame.module)
            res = resolve_attr(self.project, base, func_node.attr) if base is not None else None
            return (res if isinstance(res, AppFunc) else None), 0
        return None, 0

    def _interproc(self, callee: AppFunc, offset: int, kind: str, key: Any, bound_path: ParamPath) -> None:
        """Follow a call: bind the callee's parameter to ``bound_path`` and recurse into its body.

        Both call sites guard ``callee is not None`` (an unfollowable target escapes the arg at the
        call site), so ``callee`` is always a resolved ``AppFunc`` here.
        """
        node = callee.funcdef
        param_name = self._bound_param_name(node, offset, kind, key)
        if param_name is None:  # lands in *args/**kwargs or no matching parameter
            self._escape(bound_path)
            return
        with self._enter(("node", id(node))) as entered:
            if not entered:  # cycle / depth cap
                self._escape(bound_path)
                return
            self._mark_walked(node)  # detection rides along on this walk
            child = _Frame(node, callee.home_module, callee.owner, self.project)
            self.walk_body(node.body, {param_name: bound_path}, child)

    def _scan_callee_detected(self, callee: AppFunc) -> None:
        """Walk an app callee's body solely to detect service-client construction inside it.

        Isolated from the params dimension in three ways, so it can only add to ``_platform_services``:

        - ``env`` is empty, so no name resolves to a params path;
        - it runs under ``_params_sink``, so *any* recording — including an env-independent escalation
          such as the closure depth cap escaping the params root — is discarded rather than widening
          the view's contract;
        - it claims no ``_active`` slot of its own, counting its nesting in ``_detect_depth`` instead.
          Constructs *inside* the scanned body do still use ``_enter`` (that is how a nested def in
          scanned code can hit the depth cap at all) — the sink is what keeps that harmless.

        Skipped when this view already walked that body (whatever walked it ran detection over the
        same calls), which also terminates recursion. Scan nesting is *not* a second budget: it is
        charged against the same ``_MAX_DEPTH`` as params-following, so a chain that follows params
        and then scans reaches no further than either could alone.
        """
        key = ("node", id(callee.funcdef))
        if key in self._walked:
            return  # already swept and detected over by whatever walked it
        if self._detect_depth + len(self._active) >= _MAX_DEPTH:
            self._external_escalate()  # the unwalked remainder cannot be shown free of external input
            return
        self._mark_walked(callee.funcdef)
        self._detect_depth += 1
        try:
            with self._params_sink():
                child = _Frame(callee.funcdef, callee.home_module, callee.owner, self.project)
                self.walk_body(callee.funcdef.body, {}, child)
        finally:
            self._detect_depth -= 1

    @staticmethod
    def _bound_param_name(node: ast.AST, offset: int, kind: str, key: Any) -> str | None:
        positional = [a.arg for a in (node.args.posonlyargs + node.args.args)]
        kwonly = [a.arg for a in node.args.kwonlyargs]
        if kind == "pos":
            idx = key + offset
            if idx < len(positional):
                return positional[idx]
            return None  # lands in *args (or arity mismatch) -> caller escapes
        if key in positional or key in kwonly:
            return key
        return None  # lands in **kwargs (or unknown keyword) -> caller escapes

    # -- instance tracking (the `m = self.model(params=params); m.method()` pattern) --

    def _bind_call_args(
        self, node: ast.AST | None, target_node: ast.AST, offset: int, env: Env
    ) -> dict[str, ParamPath]:
        """Map the params-rooted arguments of a call to the callee's parameter names.

        A params-rooted argument that does not bind to a declared parameter -- it lands in the
        callee's ``*args`` / ``**kwargs``, overflows the positional arity, or names an unknown
        keyword -- *escapes* rather than being dropped, mirroring ``_interproc`` for ordinary
        calls. (``*`` / ``**`` splats at the *call* site have no resolvable path and are handled
        opaquely by ``_visit_unbound_args``.)
        """
        if node is None:
            return {}
        positional = [a.arg for a in (target_node.args.posonlyargs + target_node.args.args)]
        kwonly = [a.arg for a in target_node.args.kwonlyargs]
        bindings: dict = {}
        for i, arg in enumerate(node.args):
            path = _params_path(arg, env)
            if path is None:
                continue  # call-site splat / non-ref arg -> handled by `_visit_unbound_args`
            if i + offset < len(positional):
                bindings[positional[i + offset]] = path
            else:
                self._escape(path)  # lands in *args / arity overflow -> escalate, never drop
        for kw in node.keywords:
            if kw.arg is None:
                continue  # **-splat -> handled by `_visit_unbound_args`
            path = _params_path(kw.value, env)
            if path is None:
                continue
            if kw.arg in positional or kw.arg in kwonly:
                bindings[kw.arg] = path
            else:
                self._escape(path)  # lands in **kwargs / unknown keyword -> escalate, never drop
        return bindings

    def _maybe_build_instance(self, call_node: ast.AST, env: Env, frame: _Frame) -> _Instance | None:
        """If ``call_node`` constructs a followable app class, analyze its ``__init__``."""
        cls = self._resolve_class(call_node.func, frame)
        if cls is None:
            return None
        init = cls.find_init()
        if init is None:  # no in-app __init__ -> not trackable
            return None
        with self._enter(("node", id(init.funcdef))) as entered:
            if not entered:
                return None
            instance = _Instance(cls)
            init_env = self._bind_call_args(call_node, init.funcdef, 1, env)  # offset 1: skip self
            child = _Frame(init.funcdef, init.home_module, init.owner, self.project)
            child.instance = instance
            self.walk_body(init.funcdef.body, init_env, child)
        self._visit_unbound_args(call_node, env, frame)
        return instance

    def _follow_instance_method(self, instance: _Instance, attr: str, node: ast.AST, env: Env, frame: _Frame) -> None:
        found = instance.cls.lookup_member(attr)
        if found is not None and isinstance(found[0], _FuncDef):
            fnode, owner_ci, _ = found
            self._follow_method(fnode, owner_ci, node, env, instance, instance.param_attrs)
        else:
            self._escape_bindings(instance.param_attrs)  # .method() on the model not followable
        self._visit_unbound_args(node, env, frame)

    def _follow_method(
        self,
        funcdef: ast.AST,
        owner_ci: ClassInfo,
        node: ast.AST | None,
        env: Env,
        instance: _Instance,
        self_bindings: dict,
    ) -> None:
        """Analyze a method with ``self.<attr>`` resolving through ``self_bindings``."""
        with self._enter(("node", id(funcdef))) as entered:
            if not entered:  # cycle / depth cap (`_enter` escalates `external_services` itself)
                self._escape_bindings(self_bindings)
                return
            self._mark_walked(funcdef)  # detection rides along on this walk
            child_env = self._bind_call_args(node, funcdef, 1, env)  # offset 1: skip self
            child_env[_SELF] = self_bindings
            child = _Frame(funcdef, owner_ci.module, owner_ci, self.project)
            child.instance = instance
            self.walk_body(funcdef.body, child_env, child)

    def _resolve_class(self, func_node: ast.AST, frame: _Frame) -> ClassInfo | None:
        """Resolve a call target to an in-app ``ClassInfo`` (for the ``m = SomeClass(params)`` pattern)."""
        res: Any = None
        if isinstance(func_node, ast.Name):
            res = resolve_name(self.project, func_node.id, frame.module)
        elif isinstance(func_node, ast.Attribute) and isinstance(func_node.value, ast.Name):
            if func_node.value.id == "self" and frame.owner is not None:
                # `self.Model(params)` where `Model` is a nested class or a class-attribute alias
                # (`model = TestModel`) found up the MRO.
                res = frame.owner.resolve_class_attr(func_node.attr)
            else:
                base = resolve_name(self.project, func_node.value.id, frame.module)
                if base is not None:
                    res = resolve_attr(self.project, base, func_node.attr)
        return res.classinfo if isinstance(res, AppClass) else None

    def _read_instance_attr(self, instance: _Instance, attr: str, env: Env) -> None:
        if attr in instance.param_attrs:  # params-derived attribute read directly
            self._escape(instance.param_attrs[attr])
            return
        if attr in instance.nonparam_attrs:
            return  # assigned a non-params value -> reading it is not a dependency
        found = instance.cls.lookup_member(attr)
        if found is not None and isinstance(found[0], _FuncDef):
            fnode, owner_ci, kind = found
            if kind == "property":
                self._follow_method(fnode, owner_ci, None, env, instance, instance.param_attrs)
                return
            if kind == "method":
                # A bound method consumed wholesale (referenced, not called in place) may be
                # invoked later through the alias -- `handler = m.method; handler()` -- and its
                # `self.<attr>` reads become real then, past where we can see the call. So escape
                # everything the instance carries from params, same as consuming the instance
                # itself. (A static/class method takes no `self`, so a reference to one reads none
                # of the instance's params -> it falls through to the under-track gap below.)
                self._escape_bindings(instance.param_attrs)
                return
        # a static/class method or nested class referenced, or an attribute set at runtime and not
        # observed in __init__ -> not a dependency (the documented under-track gap).

    def _visit_unbound_args(self, node: ast.AST, env: Env, frame: _Frame) -> None:
        """Record deps in call arguments that ``_bind_call_args`` does not bind.

        A pure params ref is bound (or, when it lands in ``*args`` / ``**kwargs``, escaped) by
        ``_bind_call_args``, so it is not re-recorded here -- except a ``x.get(k, default)`` ref
        still has its *default* evaluated at the call site, so that (and only that) is visited for
        the bound refs too. ``_bind_call_args`` resolves such a call from ``args[0]`` alone.
        """
        for arg in node.args:
            if isinstance(arg, ast.Starred):
                self._visit(arg.value, env, frame, opaque=True)
            elif _params_path(arg, env) is None:
                self._visit(arg, env, frame)
            else:
                self._visit_get_default(arg, env, frame)  # bound ref: still evaluate a `.get()` default
        for kw in node.keywords:
            path = _params_path(kw.value, env)
            if kw.arg is None and path is not None:
                self._escape(path)  # params ref splatted as **kwargs
            elif path is None:
                self._visit(kw.value, env, frame)
            else:
                self._visit_get_default(kw.value, env, frame)  # bound kw ref: evaluate a `.get()` default


def _analyze_view(
    project: ProjectIndex, funcdef: ast.AST, owner: ClassInfo, module: ModuleInfo
) -> _ViewDependencyResult:
    """Statically derive one view method's param-dependency set *and* its platform-service tags.

    ``owner`` is the concrete controller ``ClassInfo`` (so ``self.helper(...)`` resolves against
    its MRO); ``module`` is the module the view is *declared* in (so free names resolve against
    that module's imports).
    """
    result = _ViewParamDependency()
    analyzer = _Analyzer(result, project)
    analyzer._active.add(("node", id(funcdef)))
    analyzer._mark_walked(funcdef)  # the view body is walked here, so a self-call needs no scan
    frame = _Frame(funcdef, module, owner, project)
    param_name = _find_params_param(funcdef)
    if param_name is None:
        # Walk the body ignoring the params escape (``*``) in case a view does not use ``params``.
        with analyzer._params_sink():
            analyzer.walk_body(funcdef.body, {}, frame)
    else:
        analyzer.walk_body(funcdef.body, {param_name: ()}, frame)
    return _ViewDependencyResult(result, analyzer._platform_services, analyzer._external_services)


class _ViewFacts(NamedTuple):
    """One view's derived facts, each dimension sorted and ready to emit."""

    params: list
    platform_services: list
    external_services: list


def _analyze_view_safe(project: ProjectIndex, funcdef: ast.AST, owner: ClassInfo, module: ModuleInfo) -> _ViewFacts:
    """Every derived fact for one view, sorted, with a blanket fail-safe around the analyzer."""
    try:
        analysis = _analyze_view(project, funcdef, owner, module)
    except Exception:  # any analyzer failure degrades to depend-on-everything, never a stale skip
        # Both service dimensions gate, so both degrade the way the params contract degrades to `*`.
        return _ViewFacts(params=["*"], platform_services=[_EXTERNAL_UNKNOWN], external_services=[_EXTERNAL_UNKNOWN])
    external = set(analysis.external_services)
    return _ViewFacts(
        params=sorted(analysis.params.normalized_contract()),
        platform_services=sorted(set(analysis.platform_services) | (external & _PLATFORM_TAGS)),
        external_services=sorted(external - _PLATFORM_TAGS),
    )


# --- entry points -------------------------------------------------------------


def analyze_app(source_root: str | Path) -> list:
    """Statically analyze an app source tree; return each view's derived facts.

    ``source_root`` is the directory of the app package (or the directory containing a single
    ``app.py``). Returns a list of dicts, one per discovered view::

        {
            "controller": "Projects",
            "controller_module": "app.project.controller",
            "controller_method": "get_geometry_view",
            "static_analysis": {
                "input_dependencies": {"params": ["length", "section"]},
                "platform_services": ["api"],
                "external_services": ["http"],
            },
        }

    ``input_dependencies`` is the **sound** — over-approximated — group, so safe to gate a recompute
    on. ``params`` is the sorted param-dependency set (``['*']`` = depends on all params); each path
    denotes that node and its entire subtree, and the set is prefix-minimal (no entry has a strict
    ancestor also present).

    ``platform_services`` over-approximates the same way (README § Soundness), so it too may gate:
    the sorted set of platform surfaces the view reaches — ``"api"``, ``"storage"``, and
    ``"integrations"`` for a run on an external worker (`viktor.external`). Two routes feed it, a
    positively identified client *construction* and a *mention* of a platform origin, because an API
    handle can arrive through ``params`` with nothing in app source ever constructing one.

    ``external_services`` over-approximates within a declared model (README § Soundness), so it may
    gate: the sorted set of categories of input the view reads besides its params — ``"http"``,
    ``"filesystem"``, ``"clock"``, ``"nondeterminism"``, or ``"unknown"`` for a capability no
    category names and for code the analyzer could not see at all. The platform is *not* among them:
    ``platform_services`` owns that ground, and code neither can see escalates to ``"unknown"`` here.

    Both service dimensions read alike: a non-empty list means the view's output is not reproducible
    from its params alone, and an **empty list is a positive claim** that it is.

    The categories are reported separately because they do not deserve the same response, and
    *which* of them warrants marking a view out of date is the caller's policy rather than this
    package's: only the caller knows, for example, that an app runs from a baked image, so a file
    that shipped with it cannot change without a redeploy that invalidates everything anyway. This
    package's job is to report what a view reads, not what to do about it.

    ``controller`` + ``controller_module`` + ``controller_method`` identify the view so the caller
    can merge each result into the matching serialized view. ``controller`` is the **entity-type
    name** the app registers the controller under — the ``import ... as <Name>`` alias in the app's
    root ``__init__.py`` (``import ProjectController as Projects`` -> ``"Projects"``). It falls back
    to the Python class name when the app has no root package (a single ``app.py``).
    """
    project = _build_project_index(source_root)
    try:
        entity_type_names = _registered_entity_type_names(project)
        results: list = []
        for controller in iter_controllers(project):
            controller_name = entity_type_names.get(id(controller.classdef), controller.name)
            for funcdef, defining_ci in iter_views(project, controller):
                facts = _analyze_view_safe(project, funcdef, controller, defining_ci.module)
                results.append(
                    {
                        "controller": controller_name,
                        "controller_module": controller.module.dotted_name,
                        "controller_method": funcdef.name,
                        "static_analysis": {
                            "input_dependencies": {
                                "params": facts.params,
                            },
                            # api | storage | integrations | unknown
                            "platform_services": facts.platform_services,
                            # http | filesystem | clock | nondeterminism | unknown
                            "external_services": facts.external_services,
                        },
                    }
                )
        return results
    finally:
        _clear_analysis_caches()


def _clear_analysis_caches() -> None:
    """Drop the memo caches keyed on this run's AST nodes and project index.

    Their keys are per-run objects, so they never hit across calls but would retain every analysed
    app's AST — a leak in a long-lived process such as the connector.
    """
    for cached in (
        _derive_locals,
        _writeback_names,
        _body_references,
        _import_time_references,
        _class_level_assignments,
        _self_assignments,
        _module_level_assignments,
        _module_value_services,
        _body_external_services,
        _class_attr_services,
        _star_import_origins,
        _classify_chain,
    ):
        cached.cache_clear()
